    /// What `published` and `group_published` read back: the page, its request's ledger, refs, spec, rows and facts.
    type PublishedPage = (
        String,
        BTreeMap<String, String>,
        Vec<String>,
        crate::next_facts::Spec,
        Vec<crate::next_facts::Row>,
        Vec<crate::next_facts::Fact>,
    );
    /// What `cut_page` gives: the scope, the run folder, then the page's text, its refs and its rows.
    type CutPage = (
        Option<Scope>,
        tempfile::TempDir,
        String,
        Vec<String>,
        Vec<(String, String)>,
    );
    /// What `gas_fixture` gives: the main and companion rows, the catalogue, the shape and the picked claims.
    type GasFixture = (
        Vec<Value>,
        Vec<Value>,
        crate::next_flow::GroupCatalogue,
        Shape,
        Vec<(String, Value)>,
    );
    /// The map point of each ranked country and the map's extent.
    type PointsAndExtent = (BTreeMap<String, [f64; 2]>, [f64; 4]);

    /// A block left out of a many-block page must add no delivery (review 11-15): the folders the delivery scan reads are the
    /// publications with a manifest, never plans, qa or rejected; a folder with no manifest is none.
    #[test]
    fn a_block_is_labelled_by_its_quantity_name() {
        use crate::answer_plan::{Block, Focus, Plan, Rel};
        let block = |rel: Rel, q: &str, name: &str| Block {
            rel,
            focus: Focus::Max,
            places: Vec::new(),
            place_words: Vec::new(),
            years: None,
            quantity: vec![(q.to_string(), name.to_string())],
            sentence: String::new(),
        };
        // sample A: a block of its own quantity, by its family id
        let a = Plan {
            blocks: vec![
                block(Rel::Ranking, "population", "人口"),
                block(Rel::Ranking, "gdp_pc", "人均GDP"),
                block(Rel::Ranking, "urban_share", " "),
            ],
            partial: false,
        };
        assert_eq!(
            block_quantity_name(Some(&a), "gdp_pc").as_deref(),
            Some("人均GDP")
        );
        assert_eq!(
            block_quantity_name(Some(&a), "urban_share"),
            None,
            "no printed name, the text step's label stays"
        );
        assert_eq!(block_quantity_name(Some(&a), "co2"), None);
        assert_eq!(block_quantity_name(None, "gdp_pc"), None);
        // sample C: blocks of one shared table, by their place in the plan
        let c = Plan {
            blocks: vec![
                block(Rel::Magnitude, "energy_balance", "能源来源与去向"),
                block(Rel::Composition, "energy_balance", "能源来源与去向"),
            ],
            partial: false,
        };
        assert_eq!(
            block_quantity_name(Some(&c), "b2:Composition").as_deref(),
            Some("能源来源与去向")
        );
        assert_eq!(block_quantity_name(Some(&c), "b3:Flow"), None);
        assert_eq!(block_quantity_name(Some(&c), "b0:Flow"), None);
        // the label: the name on the registry frame
        let frame = |r: Relation| {
            crate::shape_registry::FRAMES
                .iter()
                .find(|(x, v, _)| (*x, *v) == (r, View::Slice))
                .unwrap()
                .2[0]
        };
        assert_eq!(
            block_kicker("人均GDP", frame(Relation::Ranking), None),
            "人均GDP的高低排名"
        );
        assert_eq!(
            block_kicker("能源来源与去向", frame(Relation::Composition), None),
            "能源来源与去向：整体的构成与份额"
        );
        assert_eq!(block_kicker("人口", "", None), "人口");
        // a frame the name already says is not said twice, and the one place a block draws is named (owner 11-16 08:4x item 3)
        assert_eq!(
            block_kicker("能源来源与去向", frame(Relation::Flow), Some("德国")),
            "德国能源来源与去向"
        );
        assert_eq!(
            block_kicker("能源来源与去向", frame(Relation::Composition), Some("德国")),
            "德国能源来源与去向：整体的构成与份额"
        );
        assert_eq!(block_kicker("德国人口", "", Some("德国")), "德国人口");
        // the one place among a flow's labels (its fuels and sectors are no place); two places, none
        let labels = |l: Value| json!({"knobs": {"labels": l}});
        assert_eq!(
            one_place_name(&labels(
                json!({"DE": "德国", "G3000": "天然气", "FC_IND_E": "工业", "E7000": "电力"})
            )),
            Some("德国")
        );
        assert_eq!(
            one_place_name(&labels(
                json!({"DE": "德国", "FR": "法国", "G3000": "天然气"})
            )),
            None
        );
        assert_eq!(
            one_place_name(&labels(json!({"DEU": "德国"}))),
            Some("德国")
        );
    }

    #[test]
    fn manifested_lists_the_deliveries_the_scan_reads() {
        let dir = tempfile::tempdir().unwrap();
        assert!(manifested(dir.path()).is_empty());
        for (sub, with) in [
            ("column-b2", true),
            ("column", true),
            ("flow-b3", false),
            ("qa/column", true),
            ("rejected", true),
            ("plans", true),
        ] {
            let d = dir.path().join("publications").join(sub);
            std::fs::create_dir_all(&d).unwrap();
            if with {
                std::fs::write(d.join("manifest.json"), "{}").unwrap();
            }
        }
        assert_eq!(manifested(dir.path()), ["column", "column-b2"]);
    }

    /// The stacked page frames each block at the size its browser check showed (sample A run 5: frames at height 0 hid all
    /// three blocks): the 1440 screenshot's PNG width and height, read from the block's own QA folder; no record, no size.
    #[test]
    fn a_block_is_framed_at_the_size_its_browser_check_showed() {
        let dir = tempfile::tempdir().unwrap();
        let qa = dir.path().join("publications/qa/column-b2");
        std::fs::create_dir_all(&qa).unwrap();
        let mut png = b"\x89PNG\r\n\x1a\n\0\0\0\rIHDR".to_vec();
        png.extend(1440u32.to_be_bytes());
        png.extend(639u32.to_be_bytes());
        std::fs::write(qa.join("1440.png"), &png).unwrap();
        std::fs::write(
            qa.join("browser-qa.json"),
            r#"{"screenshots":[{"width":1440,"path":"1440.png"}]}"#,
        )
        .unwrap();
        assert_eq!(shown_size(dir.path(), "column-b2"), (1440.0, 639.0));
        assert_eq!(
            shown_size(dir.path(), "column-b3"),
            (0.0, 0.0),
            "no QA record of that block"
        );
        std::fs::write(qa.join("1440.png"), b"not a png at all, not at all").unwrap();
        assert_eq!(shown_size(dir.path(), "column-b2"), (0.0, 0.0), "not a PNG");
    }

    /// What a value in a unit code prints after it: the unit table's number suffix (never a digit, so an index prints none and
    /// its base year stays on the unit line, user 11-05 10:2x), through suffix.
    fn num_suffix(code: &str) -> String {
        suffix(next_pack::unit_number_suffix(code).unwrap_or(""))
    }

    /// The prefix of a place's name placeholder in a page's words, `{name.<code>}` (finding_of): the leaf prints the name of the
    /// code marked with its name row (the knowledge group's name table, through the ledger), so the model, which must keep every
    /// placeholder, never types which place a number on the page belongs to.
    const NAME_PLACEHOLDER: &str = "name.";

    /// The registry template whose relation (a composition) the composition recipe draws, with its stacked100 leaf node
    /// (runtime/leaves_py run.py MAIN; its data the layer's declaration, next_tree_gen), not a template this flow fills: the
    /// composition record's template is the stacked100 declaration's (node-bindings.json record.template) since P6; kept
    /// here as the list the frozen test holds and the ratchet reads as kind names.
    pub const COMPOSITION_TEMPLATES: [&str; 1] = ["stacked_bar_100"];

    /// Frozen with the flow's extent (P6 step 8): the column decimals and the map extent as the flow computed them before the
    /// visual group's rule extent, the reference the declared extent is held to (and the old fills that read them).
    /// The most decimals a column page prints a value with, whatever its rows hold.
    const COLUMN_DEC: usize = 2;

    /// The main's rows at the shape's year for the ranked countries, and the most decimals they hold (at most COLUMN_DEC): every
    /// value of a column page prints with that many.
    fn ranked_rows<'a>(f: &Filling<'a>) -> (Vec<&'a Value>, usize) {
        let (place, year) = (f.shape.place.as_str(), f.shape.year.as_str());
        let kept: Vec<&Value> = f
            .main
            .iter()
            .filter(|r| {
                r["time"] == year
                    && r["dims"][place]
                        .as_str()
                        .is_some_and(|c| f.picks.ranked.iter().any(|k| k == c))
            })
            .collect();
        let dec = held_decimals(&kept);
        (kept, dec)
    }

    /// The most decimals the rows' values hold, at most COLUMN_DEC.
    fn held_decimals(rows: &[&Value]) -> usize {
        rows.iter()
            .filter_map(|r| r["value"].as_str())
            .map(|v| v.split_once('.').map_or(0, |(_, d)| d.len()))
            .max()
            .unwrap_or(0)
            .min(COLUMN_DEC)
    }

    /// How far (degrees) a column page's map reaches past its countries' points on each side at least, clamped to the globe: a
    /// visual layout default, as RING_HUBS. No number here prints.
    const MAP_PAD: f64 = 4.0;

    /// The column page's map panel as the second layer draws it (runtime/leaves_py: column.MAP_W, and the bubbles knobs' defaults
    /// under run.MAP_STYLE: r_max, r_min, size, label_gap, inset), for the room map_extent leaves each circle's label: visual layout
    /// defaults, as MAP_PAD; no number here prints. scripts/test_leaves_bubbles.py holds them to the leaf's own.
    const MAP_W_PX: f64 = 560.0;
    const BUBBLE_R_MAX_PX: f64 = 22.0;
    const BUBBLE_R_MIN_PX: f64 = 3.0;
    const BUBBLE_LABEL_PX: f64 = 13.0;
    const BUBBLE_LABEL_GAP_PX: f64 = 4.0;
    const MAP_INSET_PX: f64 = 12.0;

    /// A label's rough width at the bubbles' label size, as the second layer measures it (prod.tw): a CJK character the size,
    /// any other about half.
    fn label_px(s: &str) -> f64 {
        s.chars()
            .map(|c| {
                if c as u32 > 0x2e7f {
                    BUBBLE_LABEL_PX
                } else {
                    0.58 * BUBBLE_LABEL_PX
                }
            })
            .sum()
    }

    /// A value as the bubbles print it bare (fact .n): `dec` places, a comma between thousands.
    fn printed_len(v: f64, dec: usize) -> usize {
        let s = format!("{:.*}", dec, v.abs());
        let int = s.split('.').next().map_or(0, str::len);
        s.len() + int.saturating_sub(1) / 3 + usize::from(v < 0.0)
    }

    /// The room (px) a circle's label needs from the circle's point to the frame's edge, (beside, above or below): its radius,
    /// the label's gap and its width (the wider of the name and the number) to the left or right; its radius, the gap and the
    /// label's two lines above or below; each past the land's hairline inset, 2 px more for the leaf's own margins.
    fn label_room(r: f64, w: f64) -> (f64, f64) {
        let edge = MAP_INSET_PX + 2.0;
        let side = r + BUBBLE_LABEL_GAP_PX + 1.0 + w + edge;
        (
            side,
            r + BUBBLE_LABEL_GAP_PX + 1.0 + 2.45 * BUBBLE_LABEL_PX + edge,
        )
    }

    /// The map's extent: the points' box, past each side as far as the circle nearest it needs for its label there (label_room,
    /// each circle's radius by its value's area as the bubbles scale it; `labels` each circle's name and number), and MAP_PAD
    /// at least, clamped to the globe. The px become degrees through the frame the leaves project it in (mapkit.View over the
    /// extent, MAP_W_PX wide: a degree of longitude W / span px, of latitude that over the cosine of the middle latitude + 2),
    /// which the padding itself changes, so the padding is grown until it holds (it only grows, the globe bounds it).
    fn map_extent(
        points: &BTreeMap<String, [f64; 2]>,
        labels: &BTreeMap<String, (f64, String)>,
        dec: usize,
    ) -> [f64; 4] {
        let vmax = labels.values().map(|(v, _)| *v).fold(0.0, f64::max);
        let room: Vec<([f64; 2], (f64, f64))> = points
            .iter()
            .map(|(code, p)| {
                let (r, w) = match labels.get(code) {
                    Some((v, name)) => {
                        let r = match vmax > 0.0 {
                            true => {
                                (BUBBLE_R_MAX_PX * (v.max(0.0) / vmax).sqrt()).max(BUBBLE_R_MIN_PX)
                            }
                            false => BUBBLE_R_MIN_PX,
                        };
                        (
                            r,
                            label_px(name).max(printed_len(*v, dec) as f64 * label_px("0")),
                        )
                    }
                    None => (BUBBLE_R_MAX_PX, label_px(code)),
                };
                (*p, label_room(r, w))
            })
            .collect();
        let least = |i: usize| points.values().map(|p| p[i]).fold(f64::INFINITY, f64::min);
        let most = |i: usize| {
            points
                .values()
                .map(|p| p[i])
                .fold(f64::NEG_INFINITY, f64::max)
        };
        let (lon0, lat0, lon1, lat1) = (least(0), least(1), most(0), most(1));
        let clamp = |e: [f64; 4]| {
            [
                e[0].max(-180.0),
                e[1].max(-90.0),
                e[2].min(180.0),
                e[3].min(90.0),
            ]
        };
        let mut ext = clamp([
            lon0 - MAP_PAD,
            lat0 - MAP_PAD,
            lon1 + MAP_PAD,
            lat1 + MAP_PAD,
        ]);
        for _ in 0..64 {
            let x_px = MAP_W_PX / (ext[2] - ext[0]);
            let y_px = x_px / ((ext[1] + ext[3]) / 2.0 + 2.0).to_radians().cos().max(0.05);
            // the degrees each side needs: the room of each point there, less how far inside the box's edge it already is
            let side = |far: &dyn Fn(&[f64; 2]) -> f64, px: f64, beside: bool| {
                room.iter()
                    .map(|(p, (h, v))| (if beside { *h } else { *v }) / px - far(p))
                    .fold(MAP_PAD, f64::max)
            };
            let next = clamp([
                ext[0].min(lon0 - side(&|p| p[0] - lon0, x_px, true)),
                ext[1].min(lat0 - side(&|p| p[1] - lat0, y_px, false)),
                ext[2].max(lon1 + side(&|p| lon1 - p[0], x_px, true)),
                ext[3].max(lat1 + side(&|p| lat1 - p[1], y_px, false)),
            ]);
            let moved = next.iter().zip(ext).any(|(a, b)| (a - b).abs() > 1e-9);
            ext = next;
            if !moved {
                break;
            }
        }
        ext
    }

    /// The map point of each ranked country (the knowledge group's, through the catalogue, kept in `out` for knobs.points) and
    /// the map's extent (map_extent: the points' box with room past each side for the labels of the circles nearest it, each
    /// circle's value its row at the year and its name the name table's, as the bubbles print them). A country without a point
    /// refuses.
    fn ranked_points(f: &Filling, out: &mut Filled) -> Result<PointsAndExtent, String> {
        let points = f.catalogue.place_points(&f.picks.ranked)?;
        out.points
            .extend(points.iter().map(|(c, p)| (c.clone(), *p)));
        if points.is_empty() {
            return Err(format!(
                "main {} ranks no country to put on a map",
                f.shape.main
            ));
        }
        let place = f.shape.place.as_str();
        let (kept, dec) = ranked_rows(f);
        // a name the table does not answer for is measured as its code (the leaf refuses a nameless place anyway)
        let names = leaf_labels(&[], &f.picks.ranked, f.catalogue).unwrap_or_default();
        let labels: BTreeMap<String, (f64, String)> = kept
            .iter()
            .filter_map(|r| {
                let code = r["dims"][place].as_str()?;
                Some((
                    code.to_string(),
                    (
                        row_value(r)?,
                        names.get(code).cloned().unwrap_or_else(|| code.to_string()),
                    ),
                ))
            })
            .collect();
        let ext = map_extent(&points, &labels, dec);
        Ok((points, ext))
    }

    use crate::anthropic_model::ToolDef;
    use crate::next_flow::{
        number_not_allowed, placeholders, worded_number, ModelRoute, CHOOSE_TOOL,
    };

    /// verify.rs (knowledge group) reads the flow's leaf page events and plan as data, by these literals in
    /// leaf_gate_event and verify_publications, not by the agent group's names: they must not drift apart.
    #[test]
    fn verify_reads_the_leaf_page_names_the_flow_writes() {
        assert_eq!(RING_ACTOR, "flow");
        assert_eq!(RING_EVENT, "next_ring_page");
        assert_eq!(LEAF_GATE_EVENT, "next_leaf_gate");
        assert_eq!(leaf_plan_ref("x"), "publications/plans/x.json");
    }

    /// GAP-2 at the pick: a recipe none of whose layers (groups expanded) draws a view the question asks for is passed
    /// over before its shape is read; network is never drawn on the new route; an unknown recipe is an error, not a pass.
    #[test]
    fn the_pick_passes_over_a_recipe_without_the_asked_view() {
        let calls = std::sync::Mutex::new(Vec::new());
        assert_eq!(
            unanswered_views(&calls, "column", "在地图上看欧盟各国").unwrap(),
            ["map/spatial"]
        );
        assert!(unanswered_views(&calls, "scmp", "在地图上看欧盟各国")
            .unwrap()
            .is_empty());
        assert!(unanswered_views(&calls, "ring", "show it on a map")
            .unwrap()
            .is_empty());
        assert!(unanswered_views(&calls, "column", "欧盟各国可再生能源占比")
            .unwrap()
            .is_empty());
        assert_eq!(
            unanswered_views(&calls, "scmp", "draw it as a network graph").unwrap(),
            ["network"]
        );
        assert!(unanswered_views(&calls, "no_such", "show it on a map")
            .unwrap_err()
            .contains("no recipe"));
        assert_eq!(
            calls.lock().unwrap().len(),
            6,
            "each ask goes through the visual group's door"
        );
    }

    /// A recipe of the leaf registry by name, as the flow reads it (the visual group's Recipes).
    fn recipe(name: &str) -> &'static Recipe {
        Hubs.recipes().iter().find(|r| r.name == name).unwrap()
    }
    const RING_RECIPE: &str = "ring";
    fn ring_order() -> &'static [String] {
        &recipe(RING_RECIPE).layers
    }
    /// The ring recipe's shape, picks and fill, as leaf_page makes them.
    fn ring_shape(tables: &[(&str, &[Value])], catalogue: &dyn Catalogue) -> Result<Shape, String> {
        shape_of(&recipe(RING_RECIPE).eats, tables, catalogue)
    }
    /// fill_of as recipe_request calls it: a recipe that binds layers external declares them over its page input (the
    /// visual group's generator, a throwaway record of its calls), which the fill keeps for draw_nodes.
    #[allow(clippy::too_many_arguments)]
    fn test_fill(
        recipe: &Recipe,
        shape: &Shape,
        picks: &Picks,
        (main, companion): (&[Value], &[Value]),
        catalogue: &dyn Catalogue,
        words: (&str, &str),
        scoped: bool,
    ) -> Result<Value, String> {
        test_fill_set(
            recipe,
            shape,
            picks,
            (main, companion),
            catalogue,
            words,
            scoped,
            None,
        )
    }
    /// test_fill with the page input's `set` (narrow_set's, as recipe_request gives it for a narrowed main).
    #[allow(clippy::too_many_arguments)]
    fn test_fill_set(
        recipe: &Recipe,
        shape: &Shape,
        picks: &Picks,
        (main, companion): (&[Value], &[Value]),
        catalogue: &dyn Catalogue,
        words: (&str, &str),
        scoped: bool,
        set: Option<Value>,
    ) -> Result<Value, String> {
        let mut page_in = (!recipe.external.is_empty())
            .then(|| page_input(recipe, shape, picks, (main, companion)));
        if let (Some(p), Some(set)) = (page_in.as_mut(), set) {
            p["set"] = set;
        }
        let calls = std::sync::Mutex::new(Vec::new());
        let asked = Asked {
            calls: &calls,
            page_in: page_in.as_ref(),
        };
        let mut fill = fill_of(
            recipe,
            shape,
            picks,
            (main, companion),
            catalogue,
            words,
            scoped,
            Some(&asked),
        )?;
        if page_in.is_some() {
            // the map shapes the leaf's ground phase reads, as recipe_request sets them before the nodes are asked (a whole
            // path: the leaf child runs in its own folder)
            if !recipe.points.is_empty() {
                fill["knobs"]["shapes"] = json!(Path::new(env!("CARGO_MANIFEST_DIR"))
                    .join("runtime/pi/assets/naturalearth-admin0-50m.geojson"));
            }
            // and laid out where leaf_page lays them out, by the repository's own nodes
            // the node's child runs in its own folder (next_leaf::ask_once), so its runtime is a whole path
            draw_nodes(
                &mut fill,
                &recipe.external,
                &calls,
                &Path::new(env!("CARGO_MANIFEST_DIR")).join("runtime"),
            )?;
        }
        Ok(fill)
    }

    /// fill_of as recipe_request calls it, its external layers declared over the page input and not laid out.
    fn fill_undrawn(recipe: &Recipe, shape: &Shape, picks: &Picks, main: &[Value]) -> Value {
        let page_in =
            (!recipe.external.is_empty()).then(|| page_input(recipe, shape, picks, (main, &[])));
        let calls = std::sync::Mutex::new(Vec::new());
        let asked = Asked {
            calls: &calls,
            page_in: page_in.as_ref(),
        };
        fill_of(
            recipe,
            shape,
            picks,
            (main, &[]),
            &Hubs,
            ("标题", "导语"),
            false,
            Some(&asked),
        )
        .unwrap()
    }

    fn ring_fill(
        shape: &Shape,
        picks: &RingPicks,
        tables: (&[Value], &[Value]),
        catalogue: &dyn Catalogue,
        words: (&str, &str),
    ) -> Result<Value, String> {
        let RingPicks { focus, t0, t1, top } = picks;
        let picks = Picks {
            focus: focus.clone(),
            t0: t0.clone(),
            t1: t1.clone(),
            top: top.clone(),
            ..Picks::default()
        };
        test_fill(
            recipe(RING_RECIPE),
            shape,
            &picks,
            tables,
            catalogue,
            words,
            false,
        )
    }

