    /// The bubbles' numbers as they print bare: the decimals asked, a comma between thousands, a minus sign; and the rough
    /// width of a name, a CJK character the label size and any other about half.
    #[test]
    fn a_labels_width_counts_its_printed_number_and_its_name() {
        assert_eq!(printed_len(18.39, 2), 5);
        assert_eq!(printed_len(1234567.0, 1), 11);
        assert_eq!(printed_len(-999.0, 0), 4);
        assert_eq!(printed_len(-1000.0, 0), 6);
        assert!((label_px("中国") - 2.0 * BUBBLE_LABEL_PX).abs() < 1e-9);
        assert!((label_px("14.90") - 5.0 * 0.58 * BUBBLE_LABEL_PX).abs() < 1e-9);
    }

    /// The extent the frozen flow gave (ranked_points over the rows, the catalogue's names and points) and the one the visual
    /// group declares (rule extent, next_tree_gen::extent_of) over the page input the flow hands it: the same rows, the map
    /// points (points.at) and the names (leaf_labels, as fill_of hands them; none when the table names a place none). Each
    /// ranked code's row at 2025 when it has one, a decoy at 2019 for each and a decoy unranked code at 2025.
    fn extents(
        values: &[(&str, Option<&str>)],
        names: &[(&str, &str)],
    ) -> ([f64; 4], [f64; 4], [f64; 4]) {
        let mut main: Vec<Value> = Vec::new();
        for (c, v) in values {
            if let Some(v) = v {
                main.push(json!({"src": format!("series:t/{c}:2025:OBS_VALUE"), "table": "t", "dims": {"country": c}, "time": "2025", "value": v}));
            }
            main.push(json!({"src": format!("series:t/{c}:2019:OBS_VALUE"), "table": "t", "dims": {"country": c}, "time": "2019", "value": "98765.4321"}));
        }
        main.push(json!({"src": "series:t/ZZ:2025:OBS_VALUE", "table": "t", "dims": {"country": "ZZ"}, "time": "2025", "value": "5000.125"}));
        let shape = Shape {
            main: "t".into(),
            place: "country".into(),
            year: "2025".into(),
            ..Default::default()
        };
        let picks = Picks {
            ranked: values.iter().map(|(c, _)| c.to_string()).collect(),
            ..Default::default()
        };
        let cat = Ledgered(
            names
                .iter()
                .map(|(c, n)| (c.to_string(), n.to_string()))
                .collect(),
        );
        let f = Filling {
            shape: &shape,
            picks: &picks,
            main: &main,
            companion: &[],
            catalogue: &cat,
            fmt: "pc".into(),
            short: "%",
            window: None,
            asked: None,
        };
        let (points, old) = ranked_points(&f, &mut Filled::default()).unwrap();
        let page_in = json!({"shape": {"place": "country", "year": "2025"}, "picks": {"ranked": picks.ranked}, "rows": main,
            "points": {"table": POINT_TABLE, "at": points}, "names": leaf_labels(&[], &picks.ranked, &cat).unwrap_or_default()});
        let reg = crate::next_tree::load_registry(&crate::next_tree::bindings());
        let rule = crate::next_tree::J::from_value(
            &json!({"rule": "extent", "frame": "map_view", "circles": "bubbles", "dec_max": 2}),
        );
        let new = crate::next_tree_gen::extent_of(
            "bubbles",
            "ext",
            &rule,
            &crate::next_tree::J::from_value(&page_in),
            &reg,
        )
        .unwrap();
        let new: Vec<f64> = new
            .to_value()
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap())
            .collect();
        let least = |i: usize| points.values().map(|p| p[i]).fold(f64::INFINITY, f64::min);
        let most = |i: usize| {
            points
                .values()
                .map(|p| p[i])
                .fold(f64::NEG_INFINITY, f64::max)
        };
        let padded = [
            (least(0) - MAP_PAD).max(-180.0),
            (least(1) - MAP_PAD).max(-90.0),
            (most(0) + MAP_PAD).min(180.0),
            (most(1) + MAP_PAD).min(90.0),
        ];
        (old, [new[0], new[1], new[2], new[3]], padded)
    }

    /// P6 step 8: the map's extent the visual group declares (rule extent) is the frozen flow's bit for bit on every branch of
    /// it, over two places' sets (an EU set, iso2; a world set, iso3): Latin and CJK names, none named (the code measured),
    /// decimals 0, 1, 2 and 3 (printed with 2, the cap), a ranked point with no row at the year (r_max by its code), every
    /// value 0 (vmax 0: r_min), negative values (the minus sign; since 11-07 held, not equal: see below), a large value (thousands commas), one point, and a box the
    /// globe clamps (Fiji and Samoa on both sides of the antimeridian); each set holding both an extent the pad alone gives
    /// (one round) and one its labels push out (several rounds).
    #[test]
    fn declared_extent_equals_the_frozen_extent_on_every_branch() {
        let sets: [([&str; 4], [&str; 4], [&str; 4]); 2] = [
            (
                ["SE", "DE", "FR", "BE"],
                ["Sweden", "Germany", "France", "Belgium"],
                ["瑞典", "德国", "法国", "比利时"],
            ),
            (
                ["USA", "CHN", "BRA", "IDN"],
                ["United States", "China", "Brazil", "Indonesia"],
                ["美国", "中国", "巴西", "印度尼西亚"],
            ),
        ];
        let mut rounds = BTreeSet::new();
        for (codes, latin, cjk) in sets {
            let named = |n: [&'static str; 4]| -> Vec<(&str, &str)> {
                codes.iter().copied().zip(n).collect()
            };
            let vals = |v: [Option<&'static str>; 4]| -> Vec<(&str, Option<&str>)> {
                codes.iter().copied().zip(v).collect()
            };
            type Case<'a> = (
                &'a str,
                Vec<(&'a str, Option<&'a str>)>,
                Vec<(&'a str, &'a str)>,
            );
            let cases: Vec<Case> = vec![
                (
                    "latin names, dec 2",
                    vals([Some("18.39"), Some("7.1"), Some("12"), Some("3.05")]),
                    named(latin),
                ),
                (
                    "cjk names, dec 1",
                    vals([Some("18.3"), Some("7.1"), Some("12"), Some("3.0")]),
                    named(cjk),
                ),
                (
                    "no names, dec 0",
                    vals([Some("18"), Some("7"), Some("12"), Some("3")]),
                    vec![],
                ),
                (
                    "3 decimals print 2, thousands",
                    vals([Some("18.391"), Some("7.1"), Some("1234567.5"), Some("3")]),
                    named(latin),
                ),
                (
                    "a ranked point with no row",
                    vals([Some("5.5"), None, Some("2"), Some("1")]),
                    named(cjk),
                ),
                (
                    "every value 0",
                    vals([Some("0"), Some("0"), Some("0"), Some("0")]),
                    named(latin),
                ),
                (
                    "every value negative",
                    vals([Some("-999"), Some("-1000.5"), Some("-3"), Some("-12.25")]),
                    named(cjk),
                ),
                (
                    "one negative",
                    vals([Some("10"), Some("-4"), Some("3"), Some("2")]),
                    named(latin),
                ),
                (
                    "one point",
                    vec![(codes[0], Some("4.2"))],
                    vec![(codes[0], cjk[0])],
                ),
            ];
            for (case, values, names) in cases {
                let (old, new, padded) = extents(&values, &names);
                // 11-07: a circle below 0 is drawn by its value's size (bubbles.py), which the frozen flow never drew (it
                // stopped the page): there the declared extent holds the frozen one, wider where such a circle needs room
                if values
                    .iter()
                    .any(|(_, v)| v.is_some_and(|v| v.starts_with('-')))
                {
                    assert!(
                        new[0] <= old[0]
                            && new[1] <= old[1]
                            && new[2] >= old[2]
                            && new[3] >= old[3],
                        "{codes:?} {case}: {new:?} does not hold {old:?}"
                    );
                    continue;
                }
                assert_eq!(
                    old.map(f64::to_bits),
                    new.map(f64::to_bits),
                    "{codes:?} {case}: {old:?} != {new:?}"
                );
                rounds.insert((codes[0], old == padded));
            }
        }
        // the globe clamps the box: Fiji and Samoa on both sides of the antimeridian
        let (old, new, _) = extents(
            &[
                ("FJ", Some("3.5")),
                ("WS", Some("1.25")),
                ("NO", Some("40")),
            ],
            &[("FJ", "斐济"), ("WS", "萨摩亚"), ("NO", "挪威")],
        );
        assert_eq!(
            old.map(f64::to_bits),
            new.map(f64::to_bits),
            "clamped: {old:?} != {new:?}"
        );
        assert!(
            old[0] == -180.0 && old[2] == 180.0,
            "the globe clamps the box: {old:?}"
        );
        assert!(
            rounds.contains(&("SE", false)) && rounds.contains(&("USA", false)),
            "labels push some extent out: {rounds:?}"
        );
        assert!(
            rounds.iter().any(|(_, pad_only)| *pad_only),
            "some extent is the pad's alone: {rounds:?}"
        );
    }

    /// Every geometry ext of a page tree (a node's view frame extent), in tree order.
    fn tree_exts(v: &Value, out: &mut Vec<Value>) {
        match v {
            Value::Object(m) => {
                if let Some(e) = m.get("geometry").and_then(|g| g.get("ext")) {
                    out.push(e.clone());
                }
                m.values().for_each(|x| tree_exts(x, out));
            }
            Value::Array(a) => a.iter().for_each(|x| tree_exts(x, out)),
            _ => {}
        }
    }

    /// P6 step 8: the q1 column page's tree holds the circles' extent the visual group declares, the one their leaf data
    /// holds (rule extent over the page input, next_tree_gen with_values; the notes name none since 11-22, at the bars), and
    /// the flow hands in none: an extent set on the page input changes nothing, a moved map point moves the tree's extent
    /// (and it is no longer the leaf's). The column recipe has had no map since v5 item 2 (11-13); the rule is the change recipe's circles' still, so
    /// the q1 page is laid out here with the circles it had (the bindings and the recipe's layers as before).
    #[test]
    fn the_trees_extent_is_the_leaf_data_s_and_the_flow_hands_in_none() {
        use crate::next_tree::J;
        let mut v = crate::next_tree::bindings().to_value();
        v["recipes"]["column"] = json!(["bars", "bubbles", "leader_notes"]);
        let overlay = J::from_value(&v);
        let column = recipe("column");
        let with_map = Recipe {
            layers: vec![
                "bars".into(),
                "bubbles".into(),
                "bubble_key".into(),
                "leader_notes".into(),
            ],
            external: vec!["bars".into(), "bubbles".into(), "leader_notes".into()],
            points: vec!["bubbles".into()],
            ..recipe_like(column)
        };
        let (_, fill, _) = q1_fills_as(&overlay, with_map);
        let fill = fill.unwrap();
        let page_in = fill["page_in"].clone();
        assert!(page_in.get("page").is_none(), "the flow hands in no extent");
        let reg = crate::next_tree::load_registry(&overlay);
        let tree_ext = |pi: &Value| -> Vec<Value> {
            let tree = crate::next_tree_gen::tree_j(
                &J::from_value(pi),
                &J::from_value(&fill),
                &reg,
                &["bubbles".to_string()],
            )
            .unwrap();
            let mut out = Vec::new();
            tree_exts(&tree.to_value(), &mut out);
            out
        };
        let leaves = &fill["knobs"]["spec"]["hero"]["leaves"];
        let leaf = leaves["bubbles"]["ext"].clone();
        assert_eq!(leaf.as_array().map(Vec::len), Some(4));
        // the notes stand at the bars (11-22): they name no extent of their own
        assert!(leaves["leader_notes"].get("ext").is_none());
        assert_eq!(tree_ext(&page_in), vec![leaf.clone()]);
        let mut handed = page_in.clone();
        handed["page"] = json!({"ext": [0.0, 0.0, 1.0, 1.0]});
        assert_eq!(
            tree_ext(&handed),
            vec![leaf.clone()],
            "an extent handed in is read by nothing"
        );
        let mut moved = page_in.clone();
        moved["points"]["at"]["SE"] = json!([30.0, 70.0]);
        let got = tree_ext(&moved);
        assert_ne!(got, vec![leaf.clone()], "a moved point moves the extent");
        assert!(
            got[0][2].as_f64().unwrap() > 30.0 && got[0][3].as_f64().unwrap() > 70.0,
            "{got:?}"
        );
    }

    /// Two-letter codes are countries (EU aside); EU27_2020 and EA20 have members, only EU27_2020 a hub row.
    struct Hubs;
    impl Catalogue for Hubs {
        fn top5(
            &self,
            _: &str,
            _: &[String],
            _: bool,
            _: Option<i32>,
            _: Option<i32>,
        ) -> crate::l5geo::Ranking {
            unreachable!()
        }
        fn places_outside(&self, _: &str, _: &[String]) -> Vec<String> {
            unreachable!()
        }
        fn source(&self) -> &Value {
            &Value::Null
        }
        fn countries(&self, codes: &[String]) -> Result<Vec<String>, String> {
            Ok(codes
                .iter()
                .filter(|c| c.len() == 2 && c.as_str() != "EU")
                .cloned()
                .collect())
        }
        fn zh_names(
            &self,
            _: &str,
            codes: &[String],
        ) -> Result<BTreeMap<String, String>, Vec<String>> {
            Ok(codes
                .iter()
                .map(|c| (c.clone(), format!("名{c}")))
                .collect())
        }
        fn members(&self, aggregate: &str) -> Result<Vec<String>, String> {
            match aggregate {
                "EU27_2020" | "EA20" => Ok(vec!["DE".into(), "FR".into()]),
                _ => Err(format!("the member list has no aggregate {aggregate}")),
            }
        }
    }

    /// Series rows of `table` over every (code of `by`, time), the other dimensions as given.
    fn ring_rows(
        table: &str,
        fixed: &[(&str, &str)],
        by: (&str, &[&str]),
        times: &[&str],
    ) -> Vec<Value> {
        let mut out = Vec::new();
        for code in by.1 {
            for t in times {
                let mut dims: Map<String, Value> = fixed
                    .iter()
                    .map(|(d, c)| (d.to_string(), json!(c)))
                    .collect();
                dims.insert(by.0.into(), json!(code));
                out.push(json!({"src": format!("series:{table}/{code}:{t}:OBS_VALUE"), "table": table, "dims": dims, "time": t, "value": "1"}));
            }
        }
        out
    }

    #[test]
    fn the_ring_shape_is_read_from_the_tables_dims_and_rows_and_each_gap_is_refused_by_name() {
        let gas = [("siec", "G3000"), ("unit", "MIO_M3"), ("geo", "EU27_2020")];
        let partners: &[&str] = &["RU", "NO", "US", "DE", "TOTAL", "AFR_OTH"];
        let main = ring_rows("imp", &gas, ("partner", partners), &["2021", "2024"]);
        let monthly = ring_rows(
            "impm",
            &gas,
            ("partner", &["RU", "NO"]),
            &["2024-01", "2024-02"],
        );
        let shape = ring_shape(&[("imp", &main), ("impm", &monthly)], &Hubs).unwrap();
        println!("ring shape {shape:?}");
        assert_eq!(
            (
                shape.place.as_str(),
                shape.hub.as_str(),
                shape.unit.as_str()
            ),
            ("partner", "EU27_2020", "MIO_M3")
        );
        assert_eq!(
            (shape.main.as_str(), shape.companion.as_str()),
            ("imp", "impm")
        );
        assert_eq!(shape.outside, ["NO", "RU", "US"]);
        assert_eq!(
            (
                shape.years.len(),
                shape.months.len(),
                shape.point,
                shape.extent[0]
            ),
            (2, 2, [10.0, 50.0], -12.6)
        );
        // q6's shape: the origins in citizen, the same hub; no table id or topic is read
        let asylum = [("sex", "T"), ("unit", "PER"), ("geo", "EU27_2020")];
        let main_q6 = ring_rows("asy", &asylum, ("citizen", partners), &["2024", "2025"]);
        let monthly_q6 = ring_rows("asym", &asylum, ("citizen", &["RU", "NO"]), &["2025-01"]);
        let q6 = ring_shape(&[("asy", &main_q6), ("asym", &monthly_q6)], &Hubs).unwrap();
        assert_eq!(
            (q6.place.as_str(), q6.hub.as_str(), q6.companion.as_str()),
            ("citizen", "EU27_2020", "asym")
        );

        let one_year = ring_rows("a", &gas, ("partner", partners), &["2025"]);
        let tj = ring_rows(
            "impm",
            &[("unit", "TJ_GCV"), ("geo", "EU27_2020")],
            ("partner", &["RU"]),
            &["2024-01"],
        );
        let all_geo = ring_rows(
            "imp",
            &[("unit", "MIO_M3"), ("partner", "RU")],
            ("geo", &["DE", "FR", "EU27_2020"]),
            &["2021", "2024"],
        );
        let two = [
            main.clone(),
            all_geo
                .iter()
                .map(|r| {
                    let mut r = r.clone();
                    r["dims"]["partner"] = json!("NO");
                    r
                })
                .collect(),
        ]
        .concat();
        let ea = ring_rows(
            "imp",
            &[("unit", "MIO_M3"), ("geo", "EA20")],
            ("partner", partners),
            &["2021", "2024"],
        );
        let siec = |rows: &[Value], code: &str| -> Vec<Value> {
            rows.iter()
                .map(|r| {
                    let mut r = r.clone();
                    r["dims"]["siec"] = json!(code);
                    r
                })
                .collect()
        };
        let mixed = [main.clone(), siec(&main, "G3200")].concat();
        let lng = siec(&monthly, "G3200");
        let monthly_mixed = [monthly.clone(), lng.clone()].concat();
        let balance = ring_rows(
            "impm",
            &[gas[0], gas[1], gas[2], ("nrg_bal", "IMP")],
            ("partner", &["RU", "NO"]),
            &["2024-01"],
        );
        for (tables, says) in [
            (
                vec![("imp", &main[..]), ("impm", &balance[..])],
                "not this shape: monthly impm nrg_bal not in main",
            ),
            (
                vec![("a", &one_year[..]), ("impm", &monthly[..])],
                "not this shape: main spans one year (2025)",
            ),
            (
                vec![("imp", &main[..])],
                "not this shape: no monthly companion",
            ),
            (
                vec![("imp", &main[..]), ("impm", &tj[..])],
                "not this shape: unit differs: main MIO_M3, monthly impm TJ_GCV",
            ),
            (
                vec![("imp", &two[..]), ("impm", &monthly[..])],
                "not this shape: no single country origin dim: partner, geo",
            ),
            (
                vec![("imp", &ea[..]), ("impm", &monthly[..])],
                "not this shape: no hub row for EA20",
            ),
            (
                vec![("imp", &mixed[..]), ("impm", &monthly[..])],
                "not this shape: main siec varies",
            ),
            (
                vec![("imp", &main[..]), ("impm", &lng[..])],
                "not this shape: monthly impm siec is G3200, main G3000",
            ),
            (
                vec![("imp", &main[..]), ("impm", &monthly_mixed[..])],
                "not this shape: monthly impm siec varies",
            ),
        ] {
            assert_eq!(ring_shape(&tables, &Hubs).unwrap_err(), says);
        }
    }

    /// The series rows of an SDMX-CSV file read as table `id` (the dims between LAST UPDATE and TIME_PERIOD), the rows whose
    /// dims `keep` takes, an empty OBS_VALUE left out.
    fn sdmx_rows(id: &str, text: &str, keep: impl Fn(&Map<String, Value>) -> bool) -> Vec<Value> {
        let mut lines = text.lines();
        let header: Vec<&str> = lines.next().unwrap().split(',').collect();
        let at = |n: &str| header.iter().position(|h| *h == n).unwrap();
        let (first, time, value) = (at("LAST UPDATE") + 1, at("TIME_PERIOD"), at("OBS_VALUE"));
        lines
            .filter_map(|l| {
                // the LAST UPDATE cell holds no comma in these files
                let f: Vec<&str> = l.split(',').collect();
                let dims: Map<String, Value> = (first..time)
                    .map(|i| (header[i].to_string(), json!(f[i])))
                    .collect();
                let key = (first..time).map(|i| f[i]).collect::<Vec<_>>().join(".");
                (!f[value].is_empty() && keep(&dims)).then(|| {
                    json!({"src": format!("series:{id}/{key}:{}:OBS_VALUE", f[time]), "table": id,
                "dims": dims, "time": f[time], "value": f[value]})
                })
            })
            .collect()
    }

    /// A claims.jsonl record binding each (column, value) at row 0.
    fn bound(id: &str, columns: &[(&str, Value)]) -> Value {
        let bindings: Vec<Value> = columns
            .iter()
            .map(|(c, v)| json!({"placeholder": format!("{{first.{c}}}"), "column": c, "row_index": 0, "value": v}))
            .collect();
        json!({"claim_id": id, "claim_bindings": bindings})
    }

    #[test]
    fn the_ring_focus_and_years_are_the_picked_member_change_claims_and_each_gap_is_refused_by_name(
    ) {
        let gas = [("siec", "G3000"), ("unit", "MIO_M3"), ("geo", "EU27_2020")];
        let mut main = ring_rows(
            "imp",
            &gas,
            ("partner", &["RU", "NO", "US", "TOTAL"]),
            &["2021", "2022", "2024"],
        );
        for r in main.iter_mut().filter(|r| r["dims"]["partner"] == "RU") {
            r["value"] = json!(if r["time"] == "2021" {
                "126027.316"
            } else {
                "37843.285"
            });
        }
        let monthly = ring_rows("impm", &gas, ("partner", &["RU", "NO"]), &["2024-01"]);
        let shape = ring_shape(&[("imp", &main), ("impm", &monthly)], &Hubs).unwrap();
        let change = |code: &str, from: Value, from_year: i64| {
            vec![
                ("members", json!(5)),
                ("to_year", json!(2024)),
                ("country_iso2", json!(code)),
                ("from_value", from),
                ("from_year", json!(from_year)),
                ("to_value", json!(37843.285)),
            ]
        };
        let c4 = bound("c4", &change("RU", json!(126027.316), 2021));
        let c1 = bound("c1", &[("value", json!(90))]);
        let c5 = bound(
            "c5",
            &[
                ("from_value", json!(1)),
                ("from_year", json!(2022)),
                ("to_value", json!(1)),
                ("to_year", json!(2024)),
            ],
        );
        let picks = |p: &[(&str, &Value)]| -> Vec<(String, Value)> {
            p.iter()
                .map(|(k, r)| (k.to_string(), (*r).clone()))
                .collect()
        };
        let got = ring_picks(
            &shape,
            &main,
            &picks(&[
                ("rank_top", &c1),
                (MEMBER_CHANGE, &c4),
                ("cut_total_change", &c5),
            ]),
        )
        .unwrap();
        // NO and US hold the same values: code order
        let top = vec!["RU".to_string(), "NO".into(), "US".into()];
        assert_eq!(
            got,
            RingPicks {
                focus: "RU".into(),
                t0: "2021".into(),
                t1: "2024".into(),
                top
            }
        );

        let no_country = bound("c4", &change("RU", json!(126027.316), 2021)[..2]);
        let off = bound("c4", &change("RU", json!(126027.3), 2021));
        let jp = bound("c4", &change("JP", json!(126027.316), 2021));
        let early = bound("c4", &change("RU", json!(126027.316), 2019));
        let flat = bound(
            "c4",
            &[
                ("country_iso2", json!("RU")),
                ("from_year", json!(2024)),
                ("to_year", json!(2024)),
            ],
        );
        for (claims, says) in [
            (
                picks(&[("change_largest_rise", &c4)]),
                "not this shape: no member change claim picked",
            ),
            (
                picks(&[("rank_top", &c1), ("cut_total_change", &c5)]),
                "not this shape: no member change claim picked",
            ),
            (
                picks(&[(MEMBER_CHANGE, &c4), (MEMBER_CHANGE, &c4)]),
                "not this shape: 2 member change claims picked",
            ),
            (
                picks(&[(MEMBER_CHANGE, &no_country)]),
                "not this shape: claim c4 names no single country",
            ),
            (
                picks(&[(MEMBER_CHANGE, &off)]),
                "not this shape: claim c4 and main rows disagree for RU at 2021",
            ),
            (
                picks(&[(MEMBER_CHANGE, &jp)]),
                "not this shape: focus JP is not a top-N origin of main imp",
            ),
            (
                picks(&[(MEMBER_CHANGE, &early)]),
                "not this shape: claim year 2019 not in main imp",
            ),
            (
                picks(&[(MEMBER_CHANGE, &flat)]),
                "not this shape: t0 2024 is not before t1 2024",
            ),
        ] {
            assert_eq!(ring_picks(&shape, &main, &claims).unwrap_err(), says);
        }

        // RING_TOP origins above RU at both years push it off the map
        let big = ["AZ", "DZ", "LY", "NG", "QA", "TR", "UA", "UK", "ZA"];
        assert_eq!(big.len(), RING_TOP);
        let mut crowded = main.clone();
        crowded.extend(
            ring_rows("imp", &gas, ("partner", &big), &["2021", "2022", "2024"])
                .into_iter()
                .map(|mut r| {
                    r["value"] = json!("200000");
                    r
                }),
        );
        let shape = ring_shape(&[("imp", &crowded), ("impm", &monthly)], &Hubs).unwrap();
        assert_eq!(
            ring_picks(&shape, &crowded, &picks(&[(MEMBER_CHANGE, &c4)])).unwrap_err(),
            "not this shape: focus RU is not a top-N origin of main imp"
        );
    }

    /// A narrowed map page (the ring recipe declares no count of its set) has no finding, so its title falls back to the
    /// text step's label, and the run records why (headline_fell_back, HEADLINE_FELL_BACK_EVENT's reason); the same page
    /// unnarrowed has its headline and records none; a page with no recipe records the pick's stop.
    #[test]
    fn a_narrowed_map_page_records_why_its_headline_fell_back() {
        let fixed = [("siec", "G3000"), ("unit", "MIO_M3"), ("geo", "EU27_2020")];
        let mut main = ring_rows(
            "imp",
            &fixed,
            (
                "partner",
                &["RU", "NO", "US", "DE", "TOTAL", "EXT_EU27_2020"],
            ),
            &["2021", "2022", "2024"],
        );
        for r in main.iter_mut().filter(|r| r["dims"]["partner"] == "RU") {
            r["value"] = json!(if r["time"] == "2021" {
                "126027.316"
            } else {
                "37843.285"
            });
        }
        for r in main
            .iter_mut()
            .filter(|r| r["dims"]["partner"] == "US" && r["time"] == "2021")
        {
            r["value"] = json!("0");
        }
        let months: Vec<String> = (2019..=2024)
            .flat_map(|y| (1..=12).map(move |m| format!("{y}-{m:02}")))
            .take(63)
            .collect();
        let months: Vec<&str> = months.iter().map(String::as_str).collect();
        let monthly = ring_rows("impm", &fixed, ("partner", &["RU", "NO"]), &months);
        let shape = ring_shape(&[("imp", &main), ("impm", &monthly)], &Hubs).unwrap();
        let change = [
            ("members", json!(5)),
            ("from_year", json!(2021)),
            ("to_year", json!(2024)),
            ("country_iso2", json!("RU")),
            ("from_value", json!(126027.316)),
            ("to_value", json!(37843.285)),
        ];
        let RingPicks { focus, t0, t1, top } = ring_picks(
            &shape,
            &main,
            &[(MEMBER_CHANGE.to_string(), bound("c4", &change))],
        )
        .unwrap();
        let picks = Picks {
            focus,
            t0,
            t1,
            top,
            ..Picks::default()
        };
        let fill = |set: Option<Value>| {
            test_fill_set(
                recipe(RING_RECIPE),
                &shape,
                &picks,
                (&main, &monthly),
                &Hubs,
                ("标题", "导语"),
                set.is_some(),
                set,
            )
            .unwrap()
        };
        let plain = fill(None);
        assert!(
            plain[HEADLINE].is_object() && plain.get(FELL_BACK).is_none(),
            "{}",
            plain[HEADLINE]
        );
        assert_eq!(headline_fell_back(Ok(&plain), false), None);
        // the ring recipe now declares its set's count (the map's drawn, 11-03): a narrowed ring page keeps its headline,
        // its set named with that count, and records no fall back
        let narrowed = fill(Some(
            json!({"words": "在本指标最高的{n}项中", "members": 3}),
        ));
        assert!(
            narrowed[HEADLINE].is_object() && narrowed.get(FELL_BACK).is_none(),
            "{}",
            narrowed[HEADLINE]
        );
        assert_eq!(
            narrowed["finding"]["set"],
            json!("在本指标最高的{drawn}项中")
        );
        assert_eq!(headline_fell_back(Ok(&narrowed), true), None);
        // a set the map does not draw (one place more than it compares): no finding, and the fall back says why
        let off = fill(Some(
            json!({"words": "在本指标最高的{n}项中", "members": 4}),
        ));
        assert!(off.get(HEADLINE).is_none() && off.get("finding").is_none());
        assert!(headline_fell_back(Ok(&off), true).is_some());
        assert_eq!(
            headline_fell_back(Err("not this shape: x"), false).as_deref(),
            Some("no recipe page: not this shape: x")
        );
        // a focus whose change starts at zero (US, 0 at 2021): the page is drawn with no finding, and the fall back gives
        // the reason, narrowed or not, never a stop at the share of its start
        let monthly = ring_rows("impm", &fixed, ("partner", &["RU", "NO", "US"]), &months);
        let from_zero = Picks {
            focus: "US".to_string(),
            t0: picks.t0.clone(),
            t1: picks.t1.clone(),
            top: picks.top.clone(),
            ..Picks::default()
        };
        for set in [
            None,
            Some(json!({"words": "在本指标最高的{n}项中", "members": 3})),
        ] {
            let scoped = set.is_some();
            let fill = test_fill_set(
                recipe(RING_RECIPE),
                &shape,
                &from_zero,
                (&main, &monthly),
                &Hubs,
                ("标题", "导语"),
                scoped,
                set,
            )
            .unwrap();
            assert!(
                fill.get(HEADLINE).is_none() && fill.get("finding").is_none(),
                "{}",
                fill[HEADLINE]
            );
            assert_eq!(
                headline_fell_back(Ok(&fill), scoped).as_deref(),
                Some("the change starts at zero: no share of its start")
            );
        }
    }

    /// A hub page totals its origins and prints each as a share of that total, so over a unit the unit table marks not
    /// additive (a chain-linked level, owner decision 11-25) its shape is refused, the refusal naming what a page over that
    /// unit may do, with an example; the same rows in an amount that adds up read as before.
    #[test]
    fn a_hub_page_over_a_unit_that_does_not_add_up_is_refused_with_what_it_may_do() {
        let partners: &[&str] = &["RU", "NO", "US", "DE", "TOTAL", "AFR_OTH"];
        let tables = |unit: &str| {
            let fixed = [("siec", "G3000"), ("unit", unit), ("geo", "EU27_2020")];
            (
                ring_rows("imp", &fixed, ("partner", partners), &["2021", "2024"]),
                ring_rows(
                    "impm",
                    &fixed,
                    ("partner", &["RU", "NO"]),
                    &["2024-01", "2024-02"],
                ),
            )
        };
        let (main, monthly) = tables("MIO_M3");
        assert!(ring_shape(&[("imp", &main), ("impm", &monthly)], &Hubs).is_ok());
        for unit in ["CLV10_MEUR", "CLV20_EUR_HAB", "PYP_MEUR"] {
            let (main, monthly) = tables(unit);
            let why = ring_shape(&[("imp", &main), ("impm", &monthly)], &Hubs).unwrap_err();
            assert_eq!(
                Some(why.clone()),
                unit_sum_refused(unit).map(|w| format!("not this shape: {w}"))
            );
            assert!(
                why.contains("the last value, a difference, a ratio or a rank")
                    && why.contains("e.g."),
                "{why}"
            );
        }
        // a rate or an index the table marks not additive (pct_family, pct_change, index_base) is no level: a hub page over
        // it is not refused for its sum, as before
        for unit in ["PC_GDP", "PCH_M1_SA"] {
            let (main, monthly) = tables(unit);
            let got = ring_shape(&[("imp", &main), ("impm", &monthly)], &Hubs);
            assert!(
                !matches!(&got, Err(e) if e.contains("does not add up")),
                "{unit}: {:?}",
                got.err()
            );
        }
        // the unit table's own word decides: an amount that adds up, a not-additive rate or index, or a code it has no row
        // for, is not refused here; a not-additive level (amount, amount_own_currency, per_capita) is
        assert_eq!(
            [
                "MIO_M3",
                "PER",
                "GWH",
                "NO_SUCH_UNIT",
                "PC_GDP",
                "PCH_M1_SA",
                "CLV_I20",
                "PD10_EUR"
            ]
            .map(unit_sum_refused),
            [None, None, None, None, None, None, None, None]
        );
        for unit in ["CLV10_MEUR", "CLV10_MNAC", "CLV20_EUR_HAB", "PYP_MEUR"] {
            assert!(unit_sum_refused(unit).is_some(), "{unit}");
        }
    }

    /// The ring page's fill on Hubs rows: its rows (no total or aggregate row), facts, unit format, share words, top list
    /// and window; the visual group's LeafFill computes it into one ring layer per name; a unit with no short form refuses.
    #[test]
    fn the_ring_fill_is_program_rules_over_the_shape_and_picks_and_the_visual_group_computes_it() {
        let rows = |unit: &str| {
            let fixed = [("siec", "G3000"), ("unit", unit), ("geo", "EU27_2020")];
            let partners: &[&str] = &["RU", "NO", "US", "DE", "TOTAL", "EXT_EU27_2020"];
            let mut main = ring_rows(
                "imp",
                &fixed,
                ("partner", partners),
                &["2021", "2022", "2024"],
            );
            for r in main.iter_mut().filter(|r| r["dims"]["partner"] == "RU") {
                r["value"] = json!(if r["time"] == "2021" {
                    "126027.316"
                } else {
                    "37843.285"
                });
            }
            // a new source: nothing at t0
            for r in main
                .iter_mut()
                .filter(|r| r["dims"]["partner"] == "US" && r["time"] == "2021")
            {
                r["value"] = json!("0");
            }
            let months: Vec<String> = (2019..=2024)
                .flat_map(|y| (1..=12).map(move |m| format!("{y}-{m:02}")))
                .take(63)
                .collect();
            let months: Vec<&str> = months.iter().map(String::as_str).collect();
            let monthly = ring_rows("impm", &fixed, ("partner", &["RU", "NO"]), &months);
            let shape = ring_shape(&[("imp", &main), ("impm", &monthly)], &Hubs).unwrap();
            let change = [
                ("members", json!(5)),
                ("from_year", json!(2021)),
                ("to_year", json!(2024)),
                ("country_iso2", json!("RU")),
                ("from_value", json!(126027.316)),
                ("to_value", json!(37843.285)),
            ];
            let picks = ring_picks(
                &shape,
                &main,
                &[(MEMBER_CHANGE.to_string(), bound("c4", &change))],
            )
            .unwrap();
            (main, monthly, shape, picks)
        };
        let (main, monthly, shape, picks) = rows("MIO_M3");
        let fill = ring_fill(&shape, &picks, (&main, &monthly), &Hubs, ("标题", "导语")).unwrap();
        // the fill byte for byte as the ring filled it before the recipe registry (10-29): a move onto the registry changes none
        // (what the visual group is sent; `drawn`, each layer's printed rows, and the dek's `finding` stay with the flow, for
        // its page checks and the text step's draft)
        let mut sent = fill.clone();
        let drawn = sent.as_object_mut().unwrap().remove("drawn").unwrap();
        let finding = sent.as_object_mut().unwrap().remove("finding").unwrap();
        // the headline from the finding joins the fill (HEADLINES, the page's title): taken out like the dek's finding, the
        // bytes sent are the ones before it
        let headline = sent.as_object_mut().unwrap().remove(HEADLINE).unwrap();
        // the ring's headline is its focus's change between the headline years as a share of the earlier (owner 11-03): RU's
        // fall, no ranking claimed
        assert_eq!(
            headline,
            json!({"title": "{name.RU}下降{lead}", "scoped": "{name.RU}下降{lead}"})
        );
        // the page input the ring layer is declared over (P6 step 3: the ring is the visual group's) stays with the flow
        // for draw_nodes, so the bytes sent, the ring's among them, are still the ones pinned below
        sent.as_object_mut().unwrap().remove("page_in").unwrap();
        // the ring's finding is its focus's change between the headline years (owner 11-03): RU fell from 2021 to 2024, its
        // two years' values and their difference the finding's own facts, kept out of the bytes compared with the map's
        // count of the places it compares (drawn), the headline's years on the ring and the map at the later year only
        assert_eq!(
            finding,
            json!({"dek": "{lead0.t}至{lead1.t}，{name.RU}下降{lead}", "scoped": "{lead0.t}至{lead1.t}，{name.RU}下降{lead}"})
        );
        let facts = sent["knobs"]["spec"]["facts"].as_object_mut().unwrap();
        let year = |t: &str| json!({"op": "last", "table": "imp", "filter": {"partner": "RU", "geo": "EU27_2020"}, "from": t, "to": t, "fmt": "mio_m3"});
        assert_eq!(
            (
                facts.remove("lead0").unwrap(),
                facts.remove("lead1").unwrap()
            ),
            (year("2021"), year("2024"))
        );
        assert_eq!(
            facts.remove("gap").unwrap(),
            json!({"op": "minus", "a": "lead0", "b": "lead1", "fmt": "mio_m3"})
        );
        assert_eq!(
            facts.remove("lead").unwrap(),
            json!({"op": "share", "a": "gap", "b": "lead0"})
        );
        assert_eq!(facts.remove("drawn").unwrap()["op"], "n");
        let hero = sent["knobs"]["spec"]["hero"].as_object_mut().unwrap();
        assert_eq!(
            hero["ring"]
                .as_object_mut()
                .unwrap()
                .remove("inside")
                .unwrap(),
            json!({"from": "2021", "to": "2024"})
        );
        let data = hero["data"].as_object_mut().unwrap();
        assert_eq!(
            (
                data.remove("halo").unwrap(),
                data.remove("legend_word").unwrap()
            ),
            (json!(false), json!("ring.map.t1"))
        );
        assert_eq!(
            crate::hash::sha256_bytes(sent.to_string().as_bytes()),
            "d728a43088b98205718a7814a2ce0ef3572d9485fc8961926831fa471dafb5e8"
        );
        assert!(
            drawn
                .as_array()
                .unwrap()
                .iter()
                .all(|r| ["map", "ring"].contains(&r["layer"].as_str().unwrap())),
            "{drawn}"
        );
        assert_eq!(fill["order"], json!(ring_order()));
        let kept = fill["rows"].as_array().unwrap();
        // RU NO US DE at three years, and RU's 63 months
        assert_eq!(kept.len(), 4 * 3 + 63);
        assert!(
            kept.iter()
                .all(|r| !["TOTAL", "EXT_EU27_2020"]
                    .contains(&r["dims"]["partner"].as_str().unwrap()))
        );
        assert!(kept
            .iter()
            .filter(|r| r["table"] == "impm")
            .all(|r| r["dims"]["partner"] == "RU"));
        let spec = &fill["knobs"]["spec"];
        let mut keys: Vec<String> = spec["facts"].as_object().unwrap().keys().cloned().collect();
        let mut want: Vec<String> = [
            "tot21",
            "tot24",
            "tot_ch",
            "ru_m_peak",
            "ru_last",
            "lab_t0",
            "lab_t1",
            "lead0",
            "lead1",
            "gap",
            "lead",
            "drawn",
        ]
        .map(String::from)
        .to_vec();
        for c in ["ru", "no", "us"] {
            want.extend([format!("{c}21"), format!("{c}24"), format!("{c}24_share")]);
        }
        // US had nothing at t0, so no change of its
        want.extend(["ru_ch".to_string(), "no_ch".into()]);
        keys.sort();
        want.sort();
        assert_eq!(keys, want);
        assert_eq!(
            spec["facts"]["tot24"]["filter"],
            json!({"geo": "EU27_2020"})
        );
        assert_eq!(
            spec["fmts"]["mio_m3"],
            json!({"scale": 1, "dec": 0, "suffix": " 百万立方米"})
        );
        assert_eq!(
            spec["hero"]["unit"],
            "单位：百万立方米；占比为名EU27_2020以外各国合计中的占比"
        );
        assert_eq!(spec["hero"]["data"]["top"], json!(["RU", "NO", "US"]));
        // 60 months ending 2024-03; fewer months start at the first
        assert_eq!(spec["hero"]["ring"]["from"], "2019-04");
        assert_eq!(
            ring_from(&["2023-01".into(), "2024-03".into()], 60).as_deref(),
            Some("2023-01")
        );
        assert_eq!(
            ring_from(&["2023-01".into(), "2024-03".into()], 12).as_deref(),
            Some("2023-04")
        );
        assert_eq!(fill["knobs"]["labels"]["RU"], "名RU");

        let order: Vec<String> = ring_order().to_vec();
        let calls = std::sync::Mutex::new(Vec::new());
        let request = crate::next_visual::Request::LeafFill {
            recipe: RING_RECIPE,
            rows: kept,
            knobs: &fill["knobs"],
            order: &order,
            runtime: Path::new("runtime"),
        };
        let Ok(crate::next_visual::Reply::Filled(page)) =
            crate::next_flow::visual_call(&calls, "leaf_fill", request)
        else {
            panic!("no filled page");
        };
        // 23 declared (lead0, lead1, gap, lead the finding's, drawn the set count); lab_t0 and lab_t1 one fact per origin outside the hub (RU NO US)
        assert_eq!(
            (page.layers.len(), page.refs.as_slice(), page.facts.len()),
            (5, &["imp".to_string(), "impm".into()][..], 27)
        );
        // the total is the countries outside the hub (RU NO US); DE is a member, TOTAL and EXT_EU27_2020 are not rows
        let tot24 = page.facts.iter().find(|f| f.key == "tot24").unwrap();
        assert_eq!((tot24.v, tot24.n), (37843.285 + 1.0 + 1.0, Some(3)));
        assert_eq!(
            (page.frame.clone(), page.w, page.h),
            (Value::Null, 1140.0, 0.0)
        );

        let (main, monthly, shape, picks) = rows("XYZ");
        assert_eq!(
            ring_fill(&shape, &picks, (&main, &monthly), &Hubs, ("", "")).unwrap_err(),
            "not this shape: unit XYZ has no row in unit-short-zh"
        );
        let (main, monthly, shape, picks) = rows("MIO_M3");
        assert_eq!(
            ring_fill(
                &shape,
                &picks,
                (&main, &monthly),
                &NoAggregateNames,
                ("", "")
            )
            .unwrap_err(),
            "not this shape: the name table names no hub EU27_2020"
        );
    }

    /// Hubs, but the name table names no aggregate code: only two-letter codes have a name.
    struct NoAggregateNames;
    impl Catalogue for NoAggregateNames {
        fn top5(
            &self,
            _: &str,
            _: &[String],
            _: bool,
            _: Option<i32>,
            _: Option<i32>,
        ) -> crate::l5geo::Ranking {
            unreachable!()
        }
        fn places_outside(&self, _: &str, _: &[String]) -> Vec<String> {
            unreachable!()
        }
        fn source(&self) -> &Value {
            &Value::Null
        }
        fn countries(&self, codes: &[String]) -> Result<Vec<String>, String> {
            Hubs.countries(codes)
        }
        fn zh_names(
            &self,
            scheme: &str,
            codes: &[String],
        ) -> Result<BTreeMap<String, String>, Vec<String>> {
            let missing: Vec<String> = codes.iter().filter(|c| c.len() != 2).cloned().collect();
            if missing.is_empty() {
                Hubs.zh_names(scheme, codes)
            } else {
                Err(missing)
            }
        }
        fn members(&self, aggregate: &str) -> Result<Vec<String>, String> {
            Hubs.members(aggregate)
        }
    }

    /// Hubs, but the EU's members are four and the euro area's two, so only the EU holds every place a page draws below.
    struct Scoped(bool);
    impl Catalogue for Scoped {
        fn top5(
            &self,
            _: &str,
            _: &[String],
            _: bool,
            _: Option<i32>,
            _: Option<i32>,
        ) -> crate::l5geo::Ranking {
            unreachable!()
        }
        fn places_outside(&self, _: &str, _: &[String]) -> Vec<String> {
            unreachable!()
        }
        fn source(&self) -> &Value {
            &Value::Null
        }
        fn countries(&self, codes: &[String]) -> Result<Vec<String>, String> {
            Hubs.countries(codes)
        }
        /// With false the name table names no aggregate code, as NoAggregateNames.
        fn zh_names(
            &self,
            scheme: &str,
            codes: &[String],
        ) -> Result<BTreeMap<String, String>, Vec<String>> {
            if self.0 {
                Hubs.zh_names(scheme, codes)
            } else {
                NoAggregateNames.zh_names(scheme, codes)
            }
        }
        fn members(&self, aggregate: &str) -> Result<Vec<String>, String> {
            match aggregate {
                "EU27_2020" => Ok(["DE", "FR", "IT", "PL"].map(String::from).to_vec()),
                "EA20" => Ok(["DE", "FR"].map(String::from).to_vec()),
                _ => Err(format!("the member list has no aggregate {aggregate}")),
            }
        }
    }

    /// The unit line's scope is the data's aggregate that holds every place drawn (EU27_2020; the euro area misses IT), named
    /// only through the name table and counted by the drawn fact: nothing the question says is printed, so a question
    /// Owner 11-22 (a story page runs against the target the law sets): has_target takes the latest target row the
    /// knowledge group handed in for this main, at a place the main holds and after its last year; a target for another
    /// table, for a place the main lacks, or at or before the last year does not count, and with none the shape fails.
    #[test]
    fn a_target_counts_only_for_this_main_at_a_held_place_after_the_last_year() {
        let mut main = ring_rows(
            "ren",
            &[("freq", "A"), ("unit", "PC")],
            ("geo", &["DE", "FR", "EU27_2020"]),
            &["2005", "2024"],
        );
        for r in main.iter_mut() {
            r["value"] = json!("20");
        }
        let target = |main_id: &str, geo: &str, t: &str| json!({"src": format!("target:{main_id}-{geo}-{t}"), "main": main_id, "dims": {"geo": geo}, "slice": {"unit": "PC"}, "time": t, "value": "42.5"});
        let eats: Vec<String> = ["annual", "one_place", "last_year", "two_ends", "has_target"]
            .map(String::from)
            .to_vec();
        let ok = [
            target("ren", "EU27_2020", "2030"),
            target("ren", "EU27_2020", "2040"),
            target("other", "EU27_2020", "2050"),
            target("ren", "US", "2060"),
        ];
        let shape = shape_of(
            &eats,
            &[("ren", &main[..]), ("targets", &ok[..])],
            &Scoped(true),
        )
        .unwrap();
        assert_eq!(
            shape.target,
            Some((
                "targets".to_string(),
                "EU27_2020".to_string(),
                "2040".to_string()
            ))
        );
        let none = [
            target("ren", "EU27_2020", "2024"),
            target("other", "EU27_2020", "2030"),
        ];
        let e = shape_of(
            &eats,
            &[("ren", &main[..]), ("targets", &none[..])],
            &Scoped(true),
        )
        .unwrap_err();
        assert!(e.contains("no target row after 2024"), "{e}");
    }

    /// I8: the EU renewable-share main reaches a target through the knowledge group's own command (the call GroupCatalogue's
    /// `targets` makes), the registry's row is the table has_target reads, and the shape ends with that target, its place and
    /// its year; a main with no target (a gas table) gets no row and the shape fails by name. The call leaves its event.
    #[test]
    fn the_registrys_target_row_reaches_a_renewable_main_s_shape() {
        let calls = std::sync::Mutex::new(Vec::new());
        let rows_for = |main: &str| match crate::next_flow::knowledge_call(
            &calls,
            "targets",
            json!({"main": main}),
            crate::next_knowledge::Request::Targets { main },
        )
        .unwrap()
        {
            crate::next_knowledge::Reply::Targets(rows) => rows,
            _ => panic!("another reply"),
        };
        let eats: Vec<String> = ["annual", "one_place", "last_year", "two_ends", "has_target"]
            .map(String::from)
            .to_vec();
        for main_id in ["nrg_ind_ren", "sdg_07_40"] {
            let main = ring_rows(
                main_id,
                &[("freq", "A"), ("nrg_bal", "REN"), ("unit", "PC")],
                ("geo", &["DE", "FR", "EU27_2020"]),
                &["2005", "2023"],
            );
            let target = rows_for(main_id);
            assert_eq!(target.len(), 1, "{main_id}");
            let by_table = target[0]["table"].as_str().unwrap().to_string();
            assert_eq!(by_table, format!("target_{main_id}"));
            let shape = shape_of(
                &eats,
                &[(main_id, &main[..]), (by_table.as_str(), &target[..])],
                &Scoped(true),
            )
            .unwrap();
            assert_eq!(
                shape.target,
                Some((by_table, "EU27_2020".to_string(), "2030".to_string()))
            );
        }
        // A table no target is read against: no rows, so no shape with a target.
        let gas = ring_rows(
            "nrg_ti_gas",
            &[("siec", "G3000"), ("unit", "MIO_M3")],
            ("geo", &["DE", "FR", "EU27_2020"]),
            &["2005", "2023"],
        );
        assert!(rows_for("nrg_ti_gas").is_empty());
        let e = shape_of(&eats, &[("nrg_ti_gas", &gas[..])], &Scoped(true)).unwrap_err();
        assert!(e.contains("no target row"), "{e}");
        let events = calls.lock().unwrap();
        assert_eq!(events.len(), 3);
        assert!(events
            .iter()
            .all(|e| e["group"] == "knowledge" && e["request"] == "targets" && e["ok"] == true));
    }

    /// Every recipe's name with its verdict, in registry order.
    type Verdicts<'a, T> = Vec<(&'a str, Result<T, String>)>;

    /// The first recipe, in registry order, whose conditions the tables meet (what the pick tries one after the other), with
    /// every recipe's verdict beside it.
    fn first_shape<'a>(
        tables: &[(&str, &[Value])],
        catalogue: &dyn Catalogue,
    ) -> (Option<&'a str>, Verdicts<'a, ()>) {
        let all: Vec<(&str, Result<(), String>)> = Hubs
            .recipes()
            .iter()
            .map(|r| {
                (
                    r.name.as_str(),
                    shape_of(&r.eats, tables, catalogue).map(|_| ()),
                )
            })
            .collect();
        (all.iter().find(|(_, v)| v.is_ok()).map(|(n, _)| *n), all)
    }

    /// The story page is tried before the one-line page and is chosen only for a request that carries a target row (has_target
    /// after the page's last year, at a held place), in both data shapes: a Eurostat table across places over twenty years with
    /// the law's target at 2030 is the story page, the same table with no target row is not (it says so), and a World Bank
    /// table of one economy over the years, which has no target to hand in and no places to compare, is the one-line page, the
    /// story page refused.
    #[test]
    fn the_story_page_is_chosen_only_for_a_request_with_a_target_row() {
        let years: Vec<String> = (2005..=2024).map(|y| y.to_string()).collect();
        let years: Vec<&str> = years.iter().map(String::as_str).collect();
        let mut eu = ring_rows(
            "ren",
            &[("freq", "A"), ("unit", "PC")],
            ("geo", &["DE", "FR", "EU27_2020"]),
            &years,
        );
        for r in eu.iter_mut() {
            r["value"] = json!("20");
        }
        let target = json!({"src": "target:ren-EU27_2020-2030", "main": "ren", "dims": {"geo": "EU27_2020"}, "slice": {"unit": "PC"}, "time": "2030", "value": "42.5"});
        let with = [target];
        let (first, all) = first_shape(&[("ren", &eu[..]), ("targets", &with[..])], &Scoped(true));
        assert_eq!(first, Some("page_story"), "{all:?}");
        let (first, all) = first_shape(&[("ren", &eu[..])], &Scoped(true));
        assert_ne!(first, Some("page_story"), "{all:?}");
        let why = all
            .iter()
            .find(|(n, _)| *n == "page_story")
            .unwrap()
            .1
            .clone()
            .unwrap_err();
        assert!(why.contains("no target row after 2024"), "{why}");
        // a target for another table does not make the main a story
        let other = [
            json!({"src": "target:x-EU27_2020-2030", "main": "x", "dims": {"geo": "EU27_2020"}, "slice": {"unit": "PC"}, "time": "2030", "value": "42.5"}),
        ];
        let (first, _) = first_shape(&[("ren", &eu[..]), ("targets", &other[..])], &Scoped(true));
        assert_ne!(first, Some("page_story"));
        // review 11-22: a target set on another slice of the table (renewables overall, the main renewables in transport),
        // or a main holding more than one code of a slice's dimension, takes no target
        for (slice, why) in [
            (json!({"unit": "PC", "nrg_bal": "REN"}), "nrg_bal absent"),
            (json!({"unit": "KTOE"}), "other unit"),
        ] {
            let t = [
                json!({"src": "target:ren-EU27_2020-2030", "main": "ren", "dims": {"geo": "EU27_2020"}, "slice": slice, "time": "2030", "value": "42.5"}),
            ];
            let (first, _) = first_shape(&[("ren", &eu[..]), ("targets", &t[..])], &Scoped(true));
            assert_ne!(first, Some("page_story"), "{why}");
        }
        let mut two = eu.clone();
        two.extend(eu.iter().map(|r| {
            let mut r = r.clone();
            r["dims"]["unit"] = json!("KTOE");
            r["src"] = json!(format!("{}k", r["src"].as_str().unwrap()));
            r
        }));
        let t = [
            json!({"src": "target:ren-EU27_2020-2030", "main": "ren", "dims": {"geo": "EU27_2020"}, "slice": {"unit": "PC"}, "time": "2030", "value": "42.5"}),
        ];
        let (first, _) = first_shape(&[("ren", &two[..]), ("targets", &t[..])], &Scoped(true));
        assert_ne!(first, Some("page_story"), "two units");

        let id = "NY.GDP.PCAP.CD@2";
        let wb: Vec<Value> = ["2000", "2005", "2010", "2015", "2020", "2022"]
            .iter()
            .map(|t| json!({"src": format!("series:{id}/IND:{t}:value"), "table": id, "dims": {"country": "IND"}, "time": t, "value": "1000"}))
            .collect();
        let (first, all) = first_shape(&[(id, &wb[..])], &WbRanked(Vec::new()));
        assert_eq!(first, Some("one_line"), "{all:?}");
        assert!(all
            .iter()
            .find(|(n, _)| *n == "page_story")
            .unwrap()
            .1
            .is_err());
    }

    /// Owner 11-22 19:0x (the sample's story put into the program): what a story page's findings step hands the findings child
    /// (story_input) is read from the shape, and every fact the child declares for the picks is one layer 1 computes from the
    /// rows (next_facts), its axis ticks the ones the leaf names. Two data shapes: a share over eight places and the whole with
    /// the law's target above every pace (the path finds even the best year short), and the same table with a target the
    /// past pace already reaches (no gap, the path says which pace gets there).
    #[test]
    fn a_story_pages_findings_are_facts_layer_1_computes_from_the_rows() {
        let years: Vec<String> = (2005..=2024).map(|y| y.to_string()).collect();
        let years: Vec<&str> = years.iter().map(String::as_str).collect();
        let places = ["DE", "FR", "IT", "PL", "SE", "FI", "MT", "LU", "EU27_2020"];
        let mut rows = ring_rows(
            "ren",
            &[("freq", "A"), ("unit", "PC")],
            ("geo", &places),
            &years,
        );
        let pace = |g: &str| match g {
            "MT" | "LU" => -0.05,
            "SE" => 0.9,
            "EU27_2020" => 0.75,
            _ => 0.5,
        };
        for r in rows.iter_mut() {
            let g = r["dims"]["geo"].as_str().unwrap().to_string();
            let y: f64 = r["time"].as_str().unwrap().parse().unwrap();
            let start = match g.as_str() {
                "EU27_2020" => 10.0,
                _ => 5.0 + 4.0 * places.iter().position(|p| *p == g).unwrap() as f64,
            };
            // the whole's best single year (2020) stands out, as the sample's does
            let jump = if g == "EU27_2020" && y >= 2020.0 {
                1.5
            } else {
                0.0
            };
            r["value"] = json!(format!("{:.1}", start + pace(&g) * (y - 2005.0) + jump));
        }
        let child = crate::next_leaf::Runner::python(
            &Path::new(env!("CARGO_MANIFEST_DIR")).join("runtime/leaves_py/findings.py"),
        );
        let story = recipe("page_story");
        // the story page places an opening picture over its header (IllusHero, the strip standing in); no other page does
        assert!(story.opening && story.strip);
        assert!(Hubs.recipes().iter().filter(|r| r.opening).count() == 1);
        for (goal, short) in [("60", true), ("35", false)] {
            let target = json!({"src": "target:ren-EU27_2020-2030", "main": "ren", "table": "target_ren",
                "dims": {"geo": "EU27_2020"}, "slice": {"freq": "A", "unit": "PC"}, "time": "2030", "value": goal});
            let targets: BTreeMap<String, Vec<Value>> =
                [("target_ren".to_string(), vec![target.clone()])].into();
            let with = [target];
            let shape = shape_of(
                &story.eats,
                &[("ren", &rows[..]), ("target_ren", &with[..])],
                &Scoped(true),
            )
            .unwrap();
            let at = shape.target.clone().unwrap();
            assert_eq!(at, ("target_ren".into(), "EU27_2020".into(), "2030".into()));
            let input =
                story_input(&shape, Some(&at), None, (&rows, &targets), "可再生能源占比").unwrap();
            // owner 11-22 23:59: a forecast held for the target year 2030 is settled by this page and by no other; held for
            // another year, or with no page picked, it stops with the refusal's own words
            let held = |year| crate::l5geo::ScopeRefusal {
                class: "forecast".into(),
                reason_zh: "将来".into(),
                hit: format!("{year}年"),
                target_year: Some(year),
            };
            // the main's event chain (chain_input), two shapes of link left out: a half-year price and two fuels a year
            let mut input = input;
            let chain_years: Vec<String> = (2010..=2024).map(|y| y.to_string()).collect();
            let chain_years: Vec<&str> = chain_years.iter().map(String::as_str).collect();
            let link = |id: &str, unit: &str, filter: &[(&str, &str)]| {
                crate::next_knowledge::ChainCompanion {
                    id: id.into(),
                    tag: id.into(),
                    position: String::new(),
                    kind: crate::next_companion::LinkKind::Flow,
                    measure_zh: "测量".into(),
                    unit: unit.into(),
                    slice: BTreeMap::new(),
                    filter: filter
                        .iter()
                        .map(|(d, c)| (d.to_string(), c.to_string()))
                        .collect(),
                    overlap: crate::next_companion::ChainOverlap {
                        places: 3,
                        years: 10,
                        first: 2010,
                        last: 2024,
                    },
                    axis: crate::next_companion::Axis::Own,
                }
            };
            let valued = |mut rows: Vec<Value>, at: f64| {
                for (i, r) in rows.iter_mut().enumerate() {
                    // a step at 2020 in each series, the band the chain finds
                    let y: f64 = r["time"].as_str().unwrap()[..4].parse().unwrap();
                    r["value"] = json!(format!(
                        "{:.0}",
                        at + if y >= 2020.0 {
                            at / 3.0
                        } else {
                            i as f64 % 2.0
                        }
                    ));
                }
                rows
            };
            let gas = [("siec", "G3000"), ("unit", "MIO_M3")];
            let air = [("airpol", "GHG"), ("unit", "MIO_T")];
            let mut chain = ChainIn::default();
            let geos = ["EU27_2020", "DE"];
            chain_add(
                &mut chain,
                &link("gas_t", "MIO_M3", &gas),
                valued(
                    ring_rows("gas_t", &gas, ("geo", &geos), &chain_years),
                    300000.0,
                ),
                "geo",
                "EU27_2020",
            );
            let half: Vec<&str> = ["2020-S1", "2020-S2", "2021-S1"].into();
            chain_add(
                &mut chain,
                &link("price_t", "EUR_KWH", &[("unit", "KWH")]),
                ring_rows("price_t", &[("unit", "KWH")], ("geo", &geos), &half),
                "geo",
                "EU27_2020",
            );
            let mut two = ring_rows(
                "solar_t",
                &[("unit", "MW"), ("siec", "RA420")],
                ("geo", &geos),
                &chain_years,
            );
            two.extend(ring_rows(
                "solar_t",
                &[("unit", "MW"), ("siec", "RA300")],
                ("geo", &geos),
                &chain_years,
            ));
            chain_add(
                &mut chain,
                &link("solar_t", "MW", &[("unit", "MW")]),
                two,
                "geo",
                "EU27_2020",
            );
            chain_add(
                &mut chain,
                &link("air_t", "MIO_T", &air),
                valued(
                    ring_rows("air_t", &air, ("geo", &geos), &chain_years),
                    2000.0,
                ),
                "geo",
                "EU27_2020",
            );
            assert_eq!(chain.tables, ["gas_t", "air_t"]);
            assert_eq!(
                chain.items[0]["filter"],
                json!({"siec": "G3000", "unit": "MIO_M3", "geo": "EU27_2020"})
            );
            assert_eq!(
                chain.items[0]["words"],
                json!({"measure": "测量", "unit": "百万立方米"})
            );
            assert_eq!(
                chain.rows.len(),
                2 * chain_years.len(),
                "the whole's rows only"
            );
            with_chain(&mut input, chain);
            assert_eq!(input["fmt_defs"]["gas_t_d0"]["suffix"], " 百万立方米");
            let input = input;
            let story_fill = json!({STORY_IN: input.clone()});
            assert!(held_settled(Some(&held(2030)), Some(&story_fill)).is_ok());
            assert!(held_settled(None, Some(&json!({}))).is_ok());
            for (r, fill) in [
                (held(2050), Some(&story_fill)),
                (held(2030), None),
                (held(2030), Some(&rows[0])),
            ] {
                match held_settled(Some(&r), fill) {
                    Err(Stop::NoTable(why)) => {
                        assert!(why.contains("out of scope (forecast"), "{why}")
                    }
                    other => panic!("{other:?}"),
                }
            }
            // the places the page names are the shape's members (fill_of names them): every place, the whole among them
            assert_eq!(shape.members.len(), places.len());
            assert_eq!(input["main"]["whole"], "EU27_2020");
            assert_eq!(input["main"]["filter"], json!({"freq": "A", "unit": "PC"}));
            assert!(!input["main"]["members"]
                .as_array()
                .unwrap()
                .iter()
                .any(|m| m == "EU27_2020"));
            // the members' map points, as recipe_request gives the findings' map angle: one inside each member's country
            let members: Vec<String> = input["main"]["members"]
                .as_array()
                .unwrap()
                .iter()
                .map(|m| m.as_str().unwrap().to_string())
                .collect();
            let points = Scoped(true).place_points(&members).unwrap();
            assert_eq!(points.len(), members.len());
            assert!(
                points["DE"][0] > 5.0
                    && points["DE"][0] < 15.0
                    && points["DE"][1] > 47.0
                    && points["DE"][1] < 55.0,
                "{points:?}"
            );
            assert_eq!(input["target"]["filter"], json!({"geo": "EU27_2020"}));
            assert_eq!(input["fmt_defs"]["pc"]["dec"], 1);
            // a pace or a difference of a share prints in percentage points
            assert_eq!(input["fmt_defs"]["story_delta"]["suffix"], POINTS.1);
            let mut asked = input.clone();
            asked["mode"] = json!("candidates");
            let found = crate::next_leaf::story(&child, &asked).unwrap();
            let ids: Vec<&str> = found["candidates"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|c| c["id"].as_str())
                .collect();
            assert!(ids.contains(&"path") && ids.contains(&"spread"), "{found}");
            assert!(ids.contains(&"chain"), "{found}");
            let picks: Vec<&str> = ["path", "need", "chain"]
                .into_iter()
                .filter(|p| ids.contains(p))
                .collect();
            asked["mode"] = json!("compose");
            asked["picks"] = json!(picks);
            let page = crate::next_leaf::story(&child, &asked).unwrap();
            // the fill as story_page leaves it over a fill that holds none of it yet
            let mut fill = json!({"knobs": {"spec": {"facts": {}, "fmts": {"time": {}}, "hero": {}}}, "rows": []});
            story_page(&mut fill, &input, &page).unwrap();
            assert_eq!(fill["rows"], input["rows"]);
            let request = fill.clone();
            let (spec, read, _) = crate::next_facts::stored_request(&request);
            let facts: BTreeMap<String, crate::next_facts::Fact> =
                crate::next_facts::compute(&spec, &read)
                    .unwrap_or_else(|e| panic!("goal {goal}: {e}"))
                    .into_iter()
                    .map(|f| (f.key.clone(), f))
                    .collect();
            // st1 11-23: the header's big numbers print each one's year from the request's ledger
            let all: Vec<crate::next_facts::Fact> = facts.values().cloned().collect();
            let ledger = crate::next_facts::leaf_ledger(&spec, &read, &all).unwrap();
            // every fact or period entry the child's sections and leaves name is one the ledger holds (a value the program
            // reads at a year has no .t.y of its own: its year is its table's period entry)
            fn named(v: &Value, out: &mut Vec<String>) {
                match v {
                    Value::String(s) if s.starts_with("fact:") || s.starts_with("period:") => {
                        out.push(s.clone())
                    }
                    Value::Array(a) => a.iter().for_each(|x| named(x, out)),
                    Value::Object(o) => o.values().for_each(|x| named(x, out)),
                    _ => {}
                }
            }
            let mut srcs = Vec::new();
            named(&page["knobs"]["spec"]["sections"], &mut srcs);
            named(&page["knobs"]["spec"]["hero"], &mut srcs);
            let missing: Vec<&String> = srcs
                .iter()
                .filter(|s| !ledger.contains_key(s.as_str()))
                .collect();
            assert!(
                missing.is_empty(),
                "goal {goal}: not in the ledger {missing:?}"
            );
            assert_eq!(facts["best"].t.as_deref(), Some("2020"));
            assert_eq!(
                (facts["best"].fmt.as_str(), facts["p_best"].fmt.as_str()),
                ("story_delta", "pc")
            );
            assert_eq!(facts["p_best"].v < facts["goal"].v, short, "goal {goal}");
            assert_eq!(facts.contains_key("gap"), short);
            // every tick the path's leaf names is one next_facts gives its axis fact
            let leaves = &page["knobs"]["spec"]["hero"]["leaves"];
            for (layer, axis) in [("target_path", "path_top"), ("gap_axis", "need_top")] {
                let named = leaves[layer]["axis"]["ticks"].as_array().unwrap().len();
                assert_eq!(
                    crate::next_facts::ticks(&facts[axis], &input["fmt_defs"])
                        .unwrap()
                        .len(),
                    named,
                    "{layer}"
                );
            }
            let layers: Vec<&str> = page["knobs"]["spec"]["sections"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|s| s["layer"].as_str())
                .collect();
            // the header's three big numbers open the story, the thesis right after (76 11-23)
            assert_eq!(layers.get(..2), Some(&["bignums", "thesis_claims"][..]));
            assert_eq!(layers.last(), Some(&"risk_notes"));
            // I28: the lead finding's conclusion is the page's headline and its text the dek, written over the draft the fill
            // held and kept by page_words over the text step's (the kicker is the text step's); each number in them is a fact
            // the page declares, and no section prints the headline's sentence again
            let mut drafted = json!({"knobs": {"spec": {"title": "draft", "dek": "draft", "end": "draft", "kicker": "k", "facts": {}, "hero": {}}}, "rows": []});
            story_page(&mut drafted, &input, &page).unwrap();
            let words = |f: &Value, k: &str| f["knobs"]["spec"][k].as_str().unwrap().to_string();
            let (title, dek) = (words(&drafted, "title"), words(&drafted, "dek"));
            // the arc's closing line replaces a draft the same way (I34), and prints no sentence the headline or dek printed
            assert_eq!(
                words(&drafted, "end"),
                page["knobs"]["spec"]["end"].as_str().unwrap(),
                "goal {goal}"
            );
            assert!(
                !words(&drafted, "end").is_empty()
                    && words(&drafted, "end") != title
                    && words(&drafted, "end") != dek
            );
            assert_eq!(
                title,
                page["knobs"]["spec"]["title"].as_str().unwrap(),
                "goal {goal}"
            );
            assert_eq!(
                dek,
                page["knobs"]["spec"]["dek"].as_str().unwrap(),
                "goal {goal}"
            );
            page_words(
                &mut drafted,
                ("text step title", "text step dek", "text step kicker"),
            );
            assert_eq!(
                (words(&drafted, "title"), words(&drafted, "dek")),
                (title.clone(), dek.clone()),
                "goal {goal}"
            );
            assert_eq!(words(&drafted, "kicker"), "text step kicker");
            let facts_declared = page["knobs"]["spec"]["facts"].as_object().unwrap();
            for (what, text) in [("title", &title), ("dek", &dek)] {
                assert!(
                    text.contains('{'),
                    "goal {goal}: the {what} prints no number: {text}"
                );
                for ph in text
                    .split('{')
                    .skip(1)
                    .filter_map(|t| t.split_once('}'))
                    .map(|(k, _)| k)
                {
                    let key = ph.split('.').next().unwrap();
                    assert!(
                        key == "name" || facts_declared.contains_key(key),
                        "goal {goal}: the {what}'s {{{ph}}} is no fact"
                    );
                }
            }
            for sec in page["knobs"]["spec"]["sections"].as_array().unwrap() {
                for part in ["title", "text"] {
                    assert!(
                        sec[part].as_str() != Some(title.as_str())
                            && sec[part].as_str() != Some(dek.as_str()),
                        "goal {goal}: {} {part} repeats the headline",
                        sec["id"]
                    );
                }
            }
            // a headline that is no wording refuses
            let mut f = json!({"knobs": {"spec": {"facts": {}, "hero": {}}}, "rows": []});
            let mut empty = page.clone();
            empty["knobs"]["spec"]["title"] = json!("  ");
            assert!(
                story_page(&mut f, &input, &empty)
                    .unwrap_err()
                    .contains("knobs.spec.title"),
                "goal {goal}"
            );
            // review 11-22: the child gives facts, sections and leaf data only; rows, formats or any other key it adds refuse,
            // and a fact the fill holds another way is never overwritten
            for (bad, why) in [
                (
                    json!({"knobs": page["knobs"], "rows": [{"src": "target:x", "value": "99"}]}),
                    "reply.rows",
                ),
                (
                    json!({"knobs": {"spec": page["knobs"]["spec"], "labels": {"DE": "x"}}}),
                    "knobs.labels",
                ),
                (
                    json!({"knobs": {"spec": {"fmts": {"pc": {"scale": 100}}}}}),
                    "knobs.spec.fmts",
                ),
            ] {
                let mut f = json!({"knobs": {"spec": {"facts": {}, "hero": {}}}, "rows": []});
                let got = story_page(&mut f, &input, &bad).unwrap_err();
                assert!(got.contains(why), "{got}");
            }
            let mut f = json!({"knobs": {"spec": {"facts": {"goal": {"table": "x"}}, "hero": {}}}, "rows": []});
            let got = story_page(&mut f, &input, &page).unwrap_err();
            assert!(got.contains("knobs.spec.facts.goal"), "{got}");
        }
    }

