    /// q3 (欧盟各国发电结构) from the total fetch to the page: the program's second fetch asks the 14 group inputs for the 20
    /// largest and 5 more (COMPOSITION_RESERVE), marked sum_input with the first fetch's file and sheet (no sheet, picks or
    /// narrow of its own, so its rows become no candidate: test_page_build_wiring section 18); the composition recipe is the
    /// first that reads the shape, and its fill draws 20 bars of 4 parts (each bar's nuclear row of 0, as DE's, a part declared
    /// zero and named in a line, not a segment), each other part's cells the input rows its own sum fact filters; the 7 other countries are named in total
    /// order, the 5 fetched past the bars first.
    #[test]
    fn q3_walks_from_the_total_fetch_through_the_sum_inputs_to_twenty_bars_of_four_groups() {
        let (first, args, event, main, sums) = q3_tables(&[]);
        assert_eq!(
            args["sum_input"],
            json!({"main": "data/main.csv", "sheet": "0123456789abcdef"})
        );
        assert!(["sheet", "picks", "narrow", "sum_year"]
            .iter()
            .all(|k| !args.contains_key(*k)));
        assert_eq!(args["years"], json!({"start": 2024, "end": 2024}));
        let asked = |d: &str| {
            args["filters"]
                .as_array()
                .unwrap()
                .iter()
                .find(|f| f["dimension"] == d)
                .unwrap()["values"]
                .clone()
        };
        assert_eq!(asked("siec").as_array().unwrap().len(), 14);
        assert_eq!(asked("geo"), json!(Q3_GEOS[..25]));
        assert_eq!(
            (&event["reserve"], &event["left_out"]),
            (&json!(5), &json!(2))
        );
        assert_eq!(sums.len(), 25 * 13);
        let fill = q3_fill(&main, &sums).unwrap();
        let spec = &fill["knobs"]["spec"];
        let leaf = &spec["hero"]["leaves"]["stacked100"];
        let bars = leaf["bars"].as_array().unwrap();
        assert_eq!(
            bars.iter().map(|b| b["code"].clone()).collect::<Vec<_>>(),
            Q3_GEOS[..20].iter().map(|g| json!(g)).collect::<Vec<_>>()
        );
        assert_eq!(
            leaf["parts"],
            json!(["fossil", "renewable", "other", "nuclear"])
        );
        // every word of the picture is marked with where it is read: the totals' head is the total code's name row
        assert_eq!(
            leaf["total_head"],
            json!([{"src": "name:zh_names:siec:TOTAL"}])
        );
        assert_eq!(
            fill["knobs"]["named"]["name:zh_names:siec:TOTAL"],
            json!("名TOTAL")
        );
        for words in [
            &leaf["title"],
            &leaf["unit"],
            &leaf["total_head"],
            &leaf["others"]["head"],
        ]
        .into_iter()
        .chain(leaf["lines"].as_array().unwrap())
        {
            assert!(
                words
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|w| w["src"].is_string()),
                "{words} holds no src"
            );
        }
        let rows = fill["rows"].as_array().unwrap();
        for bar in bars {
            let code = bar["code"].as_str().unwrap();
            // three drawn parts and nuclear declared zero: every bar accounts for its 4 parts
            assert_eq!(
                bar["cells"].as_object().unwrap().keys().collect::<Vec<_>>(),
                ["fossil", "other", "renewable"],
                "{code}"
            );
            assert!(
                leaf["zero"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|z| z["bar"] == code && z["part"] == "nuclear"),
                "{code}"
            );
            for (group, cells) in bar["cells"].as_object().unwrap() {
                let [_, sum_key, share_key] = composition_keys(group, code);
                let fact = &spec["facts"][&sum_key];
                assert_eq!(
                    (fact["op"].as_str(), &fact["filter"]["geo"]),
                    (Some("value"), &json!(code))
                );
                let filtered: Vec<String> =
                    serde_json::from_value(fact["filter"]["siec"].clone()).unwrap();
                // each cell is a row its group's sum fact selects, and the fact selects no row the bar does not draw
                let srcs: Vec<&str> = cells
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|c| c.as_str().unwrap())
                    .collect();
                let selected: Vec<&str> = rows
                    .iter()
                    .filter(|r| {
                        r["dims"]["geo"] == code
                            && r["dims"]["siec"]
                                .as_str()
                                .is_some_and(|c| filtered.iter().any(|k| k == c))
                    })
                    .map(|r| r["src"].as_str().unwrap())
                    .collect();
                assert_eq!(srcs, selected, "{code} {group}");
                assert_eq!(bar["share_text"][group], json!(format!("fact:{share_key}")));
                assert_eq!(
                    spec["facts"][&share_key]["b"],
                    json!(format!("total.{code}"))
                );
            }
        }
        assert_eq!(leaf["others"]["codes"], json!(Q3_GEOS[20..]));
        assert_eq!(
            spec["facts"]["comp_others"]["filter"]["geo"],
            json!(Q3_GEOS[20..])
        );
        assert_eq!(
            spec["facts"]["comp_bars"]["filter"]["geo"],
            json!(Q3_GEOS[..20])
        );
        // the cut and the zero line: nuclear by its name, then the 20 bars' names in total order, no place left out
        let lines = leaf["lines"].as_array().unwrap();
        assert_eq!(lines.len(), 2, "{lines:?}");
        let mut zero_line = vec![
            json!({"src": "name:zh_names:siec_group:nuclear"}),
            json!({"w": "为零的国家："}),
        ];
        for (k, g) in Q3_GEOS[..20].iter().enumerate() {
            if k > 0 {
                zero_line.push(json!({"w": "、"}));
            }
            zero_line.push(json!({"src": format!("name:zh_names:iso2:{g}")}));
        }
        assert_eq!(lines[1], Value::Array(zero_line));
        assert_eq!(
            spec["facts"]["zero.nuclear"]["filter"],
            json!({"geo": Q3_GEOS[..20], "siec": ["N900H"]})
        );
        assert_eq!(spec["facts"]["zero.nuclear"]["op"], "zeros");
        assert_eq!(
            (
                &fill["composition"]["dropped"],
                &fill["composition"]["left_out"]
            ),
            (&json!([]), &json!(Q3_GEOS[25..]))
        );
        // the record's template is the stacked100 declaration's (its registry record), the frozen list's one composition template
        assert_eq!(
            fill["composition"]["template"],
            json!(COMPOSITION_TEMPLATES[0])
        );
        // the page-level fields are drafted for the composition it draws, not the ranking the first fetch's chart is
        assert_eq!(
            page_lead(Some(&fill), &[]),
            Some((Relation::Composition, View::Slice))
        );
        let drafts = next_page::draft_for(&[], &[], Vec::new(), page_lead(Some(&fill), &[]));
        let composition = crate::shape_registry::FRAMES
            .iter()
            .find(|(r, v, _)| (*r, *v) == (Relation::Composition, View::Slice))
            .unwrap()
            .2;
        assert!(format!("{drafts:?}").contains(composition[0]), "{drafts:?}");
        // the first fetch's claims are the page's only claims: the sum inputs carry none
        assert_eq!(first.claims.len(), 1);
    }

    /// A place whose parts do not add up to its total (PT's 2024 TOTAL is 0.631 GWh under them, 1.2e-5 of its 51089; here the
    /// fixture's scaled PT is set 100 GWh under, 3.3e-4 of its total, past the same 1e-5) is no bar: the 21st by total
    /// takes its place, one line by its name gives the gap as a minus fact of two facts over its own rows, and it is never
    /// in the line of the other countries, which counts the rest again. The page still stops when more than a quarter of the
    /// bars are left out, when the question names a place left out, and when the bars fall short with countries unfetched.
    #[test]
    fn a_place_whose_parts_miss_its_total_is_said_and_the_next_by_total_takes_its_bar() {
        let (_, _, _, main, sums) = q3_tables(&[("PT", 100.0)]);
        let fill = q3_fill(&main, &sums).unwrap();
        let spec = &fill["knobs"]["spec"];
        let leaf = &spec["hero"]["leaves"]["stacked100"];
        let bars: Vec<&str> = leaf["bars"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b["code"].as_str().unwrap())
            .collect();
        let want: Vec<&str> = Q3_GEOS[..21]
            .iter()
            .copied()
            .filter(|g| *g != "PT")
            .collect();
        assert_eq!(bars, want);
        assert_eq!(leaf["others"]["codes"], json!(Q3_GEOS[21..]));
        assert_eq!(
            spec["facts"]["comp_others"]["filter"]["geo"],
            json!(Q3_GEOS[21..])
        );
        assert_eq!(fill["composition"]["dropped"], json!(["PT"]));
        // the gap: the inputs' sum less the total, each a fact over PT's own rows, never a typed number
        assert_eq!(
            spec["facts"]["gap.PT"],
            json!({"op": "minus", "a": "drop_sum.PT", "b": "total.PT", "fmt": "comp_gap"})
        );
        let inputs: Vec<String> =
            serde_json::from_value(spec["facts"]["drop_sum.PT"]["filter"]["siec"].clone()).unwrap();
        assert_eq!(inputs.len(), 14);
        assert_eq!(
            spec["facts"]["total.PT"]["filter"],
            json!({"geo": "PT", "siec": "TOTAL"})
        );
        assert!(spec["fmts"]["comp_gap"]["dec"]
            .as_u64()
            .is_some_and(|d| d >= 1));
        let lines = leaf["lines"].as_array().unwrap();
        assert_eq!(lines.len(), 3, "the cut, PT's and the zero nuclear line");
        assert_eq!(
            lines[1],
            json!([{"src": "name:zh_names:iso2:PT"}, {"w": "：各组之和与合计相差 "}, {"src": "fact:gap.PT"},
            {"w": "，未列入图中，由合计次大的国家递补"}])
        );
        assert!(
            fill["rows"]
                .as_array()
                .unwrap()
                .iter()
                .any(|r| r["dims"]["geo"] == "PT"),
            "PT's rows are read for its line"
        );
        // a place the question names is never left out (named_dropped, by code)
        assert!(
            named_dropped(&fill, &[crate::l5geo::Place::Country("PT".into())])
                .unwrap_err()
                .contains("PT")
        );
        assert!(named_dropped(
            &fill,
            &[
                crate::l5geo::Place::Region,
                crate::l5geo::Place::Country("DE".into())
            ]
        )
        .is_ok());
        // more than a quarter of the bars left out: 6 of 20
        let six: Vec<(&str, f64)> = ["FR", "IT", "ES", "PL", "SE", "NL"]
            .iter()
            .map(|g| (*g, 100.0))
            .collect();
        let (_, _, _, main, sums) = q3_tables(&six);
        assert!(
            q3_fill(&main, &sums)
                .unwrap_err()
                .contains("more than a quarter"),
            "six left out"
        );
        // five is a quarter: the page goes out with the five next by total
        let (_, _, _, main, sums) = q3_tables(&six[..5]);
        assert_eq!(
            q3_fill(&main, &sums).unwrap()["knobs"]["spec"]["hero"]["leaves"]["stacked100"]["bars"]
                .as_array()
                .unwrap()
                .len(),
            20
        );
        // fewer bars than asked while countries were left unfetched: the sum inputs end before the bars are full
        let (_, _, _, main, sums) = q3_tables(&[("PT", 100.0)]);
        let cut: Vec<Value> = sums
            .into_iter()
            .filter(|r| {
                ![
                    "RO", "EL", "HU", "BG", "DK", "SK", "IE", "HR", "SI", "LT", "EE", "LV", "CY",
                ]
                .contains(&r["dims"]["geo"].as_str().unwrap())
            })
            .collect();
        let err = q3_fill(&main, &cut).unwrap_err();
        assert!(err.contains("short of"), "{err}");
        // a table of 22 countries, all fetched: three left out leave 19 bars, under a quarter, and the page still stops, never
        // printing a cut of 19 as the largest 20
        let (_, _, _, main, sums) = q3_tables(&[("FR", 100.0), ("IT", 100.0), ("ES", 100.0)]);
        let kept = |r: &Value| {
            r["dims"]["geo"] == "EU27_2020"
                || Q3_GEOS[..22].contains(&r["dims"]["geo"].as_str().unwrap())
        };
        let (main, sums): (Vec<Value>, Vec<Value>) = (
            main.into_iter().filter(|r| kept(r)).collect(),
            sums.into_iter().filter(|r| kept(r)).collect(),
        );
        let err = q3_fill(&main, &sums).unwrap_err();
        assert!(
            err.contains("19 places add up") && err.contains("short of 20"),
            "{err}"
        );
    }

    /// A part that is 0 in a bar is declared zero with its rows and said by name in one line, never a dropped segment; a
    /// part with no row is no zero (it stays empty, which the leaf drops as no row, failing notes_dropped as before), and a
    /// part above 0 is drawn. The page check zeros_declared passes when each declared part's rows are 0 in the fetched rows,
    /// and fails when one is not, or has none. Two shapes: every bar's nuclear 0 (q3 2024), and FR's nuclear above 0 with
    /// IT's nuclear row missing.
    #[test]
    fn a_part_that_is_zero_is_declared_and_said_and_the_page_check_holds_it_to_the_data() {
        let (_, _, _, main, sums) = q3_tables(&[]);
        let mut fill = q3_fill(&main, &sums).unwrap();
        zero_rows(&mut fill, &sums);
        let zeros = declared_zeros(&fill);
        assert_eq!(zeros.len(), 20);
        let rows_of = |z: &Value| z["codes"][0]["rows"].as_array().unwrap().clone();
        assert!(
            zeros
                .iter()
                .all(|z| z["part"] == "nuclear"
                    && rows_of(z).iter().all(|r| r["value"] == json!(0.0)))
        );
        let check = zeros_check(&zeros).unwrap();
        assert_eq!((check.name, check.passed), ("zeros_declared", true));
        // the declaration does not match the data: a row above 0, or a part with no row, fails
        let mut off = zeros.clone();
        off[0]["codes"][0]["rows"][0]["value"] = json!(1.5);
        let failed = zeros_check(&off).unwrap();
        assert_eq!(
            (failed.passed, &failed.measured["not_zero"][0]["part"]),
            (false, &json!("DE:nuclear"))
        );
        let mut none = zeros.clone();
        none[1]["codes"][0]["rows"] = json!([]);
        assert!(!zeros_check(&none).unwrap().passed);
        assert!(
            zeros_check(&[]).is_none(),
            "a page that declares no zero gets no such check"
        );

        // FR's nuclear above 0 (its total by as much), IT's nuclear row gone
        let (_, _, _, mut main, mut sums) = q3_tables(&[]);
        let nuclear = |r: &Value, g: &str| r["dims"]["geo"] == g && r["dims"]["siec"] == "N900H";
        sums.iter_mut().find(|r| nuclear(r, "FR")).unwrap()["value"] = json!("1000");
        let fr = main.iter_mut().find(|r| r["dims"]["geo"] == "FR").unwrap();
        fr["value"] = json!(format!("{}", row_value(fr).unwrap() + 1000.0));
        sums.retain(|r| !nuclear(r, "IT"));
        let mut fill = q3_fill(&main, &sums).unwrap();
        zero_rows(&mut fill, &sums);
        let leaf = &fill["knobs"]["spec"]["hero"]["leaves"]["stacked100"];
        let bar = |g: &str| {
            leaf["bars"]
                .as_array()
                .unwrap()
                .iter()
                .find(|b| b["code"] == g)
                .unwrap()
                .clone()
        };
        assert!(
            bar("FR")["cells"]["nuclear"].is_array(),
            "a part above 0 is drawn"
        );
        assert!(bar("IT")["cells"]["nuclear"].is_null());
        assert_eq!(
            leaf["empty"],
            json!([{"bar": "IT", "part": "nuclear"}]),
            "no row is empty, never zero"
        );
        let declared: Vec<&str> = leaf["zero"]
            .as_array()
            .unwrap()
            .iter()
            .map(|z| z["bar"].as_str().unwrap())
            .collect();
        assert!(
            !declared.contains(&"FR") && !declared.contains(&"IT") && declared.len() == 18,
            "{declared:?}"
        );
        let names = |line: &Value| -> Vec<String> {
            line.as_array()
                .unwrap()
                .iter()
                .filter_map(|w| w["src"].as_str().map(String::from))
                .collect()
        };
        let zero_line = names(&leaf["lines"][1]);
        assert!(
            !zero_line.contains(&"name:zh_names:iso2:FR".to_string())
                && !zero_line.contains(&"name:zh_names:iso2:IT".to_string())
        );
        assert!(zeros_check(&declared_zeros(&fill)).unwrap().passed);
    }

    /// AT's fossil rows and its other rows set to 0 (its total less them): fossil has a row of every code, all 0, so it is
    /// declared zero and named in a line; other is 0 on every row it has while E7000 has none (the table publishes none), so
    /// it is empty, never declared zero and never said 0.
    #[test]
    fn a_group_with_a_code_of_no_row_is_never_declared_zero() {
        let (_, _, _, mut main, mut sums) = q3_tables(&[]);
        let groups = next_params::group_inputs("nrg_bal_peh", "siec").unwrap();
        let codes_of = |g: &str| groups.iter().find(|(name, _)| name == g).unwrap().1.clone();
        let (fossil, other) = (codes_of("fossil"), codes_of("other"));
        assert!(
            other.contains(&"E7000".to_string())
                && !sums.iter().any(|r| r["dims"]["siec"] == "E7000")
        );
        let mut less = 0.0;
        for r in sums.iter_mut().filter(|r| r["dims"]["geo"] == "AT") {
            let code = r["dims"]["siec"].as_str().unwrap().to_string();
            if fossil.contains(&code) || other.contains(&code) {
                less += row_value(r).unwrap();
                r["value"] = json!("0");
            }
        }
        let total = main.iter_mut().find(|r| r["dims"]["geo"] == "AT").unwrap();
        total["value"] = json!(format!("{}", row_value(total).unwrap() - less));
        let mut fill = q3_fill(&main, &sums).unwrap();
        zero_rows(&mut fill, &sums);
        let leaf = &fill["knobs"]["spec"]["hero"]["leaves"]["stacked100"];
        let at = |key: &str| -> Vec<String> {
            leaf[key]
                .as_array()
                .unwrap()
                .iter()
                .filter(|z| z["bar"] == "AT")
                .map(|z| z["part"].as_str().unwrap().to_string())
                .collect()
        };
        assert_eq!(at("zero"), ["fossil", "nuclear"]);
        assert_eq!(at("empty"), ["other"]);
        let lines = leaf["lines"].as_array().unwrap();
        let said = |part: &str| {
            lines
                .iter()
                .any(|l| l[0]["src"] == format!("name:zh_names:siec_group:{part}"))
        };
        assert!(
            said("fossil") && said("nuclear") && !said("other"),
            "{lines:?}"
        );
        // every code of AT's fossil read again from the fetched rows, each 0, all of them declared
        let zeros = declared_zeros(&fill);
        let fossil_at = zeros
            .iter()
            .find(|z| z["bar"] == "AT" && z["part"] == "fossil")
            .unwrap();
        assert_eq!(fossil_at["codes"].as_array().unwrap().len(), fossil.len());
        assert!(zeros_check(&zeros).unwrap().passed);
    }

    /// zeros_declared reads each declared part again from the fetched rows by its place, its group's codes and its year: a
    /// declared src of another bar, a row of the part left out of the declaration, a code with no row, a row not 0, and a
    /// fill that declares zeros with no such reading each fail; the reading the fill made passes.
    #[test]
    fn zeros_declared_reads_each_zero_part_again_from_the_fetched_rows() {
        let (_, _, _, mut main, mut sums) = q3_tables(&[]);
        let groups = next_params::group_inputs("nrg_bal_peh", "siec").unwrap();
        let fossil = groups
            .iter()
            .find(|(name, _)| name == "fossil")
            .unwrap()
            .1
            .clone();
        let mut less = 0.0;
        for r in sums.iter_mut().filter(|r| {
            r["dims"]["geo"] == "AT" && fossil.iter().any(|c| r["dims"]["siec"] == c.as_str())
        }) {
            less += row_value(r).unwrap();
            r["value"] = json!("0");
        }
        let total = main.iter_mut().find(|r| r["dims"]["geo"] == "AT").unwrap();
        total["value"] = json!(format!("{}", row_value(total).unwrap() - less));
        let mut fill = q3_fill(&main, &sums).unwrap();
        let unread = declared_zeros(&fill);
        assert!(
            !zeros_check(&unread).unwrap().passed,
            "declared zeros with no reading of the fetched rows"
        );
        zero_rows(&mut fill, &sums);
        let zeros = declared_zeros(&fill);
        assert!(zeros_check(&zeros).unwrap().passed);
        let i = zeros
            .iter()
            .position(|z| z["bar"] == "AT" && z["part"] == "fossil")
            .unwrap();
        let fails = |zeros: Vec<Value>, why: &str| {
            let check = zeros_check(&zeros).unwrap();
            assert!(!check.passed, "{why}");
            assert!(
                check.measured["not_zero"].to_string().contains("AT:fossil"),
                "{why}: {}",
                check.measured
            );
        };
        // a declared src that is no row of AT's fossil (FR's nuclear row in place of one of AT's)
        let fr = sums
            .iter()
            .find(|r| r["dims"]["geo"] == "FR" && r["dims"]["siec"] == "N900H")
            .unwrap()["src"]
            .clone();
        let mut foreign = zeros.clone();
        foreign[i]["declared"][0] = fr;
        fails(foreign, "a src of another bar and part");
        // a row of the part left out of the declaration
        let mut left = zeros.clone();
        left[i]["declared"].as_array_mut().unwrap().pop();
        fails(left, "a row left out");
        // a code with no row in the fetched rows
        let mut missing = zeros.clone();
        missing[i]["codes"][0]["rows"] = json!([]);
        fails(missing, "a code with no row");
        // a row that is not 0
        let mut above = zeros.clone();
        above[i]["codes"][1]["rows"][0]["value"] = json!(3.0);
        fails(above, "a row above 0");
    }

    /// A composition page's finding: of its bars, the place whose first part (fossil, the leaf's accent) is the largest share
    /// of its total; the dek and the headline name the place and the part by their name placeholders and print the share as a
    /// fact over that bar's sum and total facts, never a typed number; the kicker is the registry's composition words. With
    /// every bar's share alike as printed there is no finding, so no headline.
    #[test]
    fn a_composition_page_s_headline_names_the_place_whose_first_part_is_the_largest_share() {
        let (_, _, _, mut main, mut sums) = q3_tables(&[]);
        // the tables as fetched give every country DE's mix, so no bar's share is its own: no finding
        let fill = q3_fill(&main, &sums).unwrap();
        assert!(
            fill[HEADLINE].is_null() && fill["finding"].is_null(),
            "{}",
            fill["finding"]
        );
        // IT's fossil inputs half again, its total by as much: IT's fossil share is the largest
        let fossil = next_params::group_inputs("nrg_bal_peh", "siec").unwrap()[0]
            .1
            .clone();
        let mut more = 0.0;
        for r in sums.iter_mut().filter(|r| {
            r["dims"]["geo"] == "IT" && fossil.iter().any(|c| r["dims"]["siec"] == c.as_str())
        }) {
            let v = row_value(r).unwrap();
            more += v / 2.0;
            r["value"] = json!(format!("{}", v * 1.5));
        }
        let total = main.iter_mut().find(|r| r["dims"]["geo"] == "IT").unwrap();
        total["value"] = json!(format!("{}", row_value(total).unwrap() + more));
        let fill = q3_fill(&main, &sums).unwrap();
        let spec = &fill["knobs"]["spec"];
        assert_eq!(
            fill[HEADLINE]["title"],
            json!("{name.IT}{name.fossil}占比最高，达{comp_top}")
        );
        assert_eq!(
            fill["finding"]["dek"],
            json!("{lead1.t}，{name.IT}{name.fossil}占比最高，为{comp_top}")
        );
        // a cut composition (places left out) names the set it ranks in: the registry's composition set words
        assert_eq!(
            fill["finding"]["scoped"],
            json!("{lead1.t}，图中各国中，{name.IT}{name.fossil}占比居首，为{comp_top}")
        );
        assert_eq!(fill["finding"]["set"], json!("图中各国中"));
        assert_eq!(
            fill[HEADLINE]["scoped"],
            json!("图中各国中{name.IT}{name.fossil}占比居首，达{comp_top}")
        );
        assert_eq!(
            spec["facts"][COMPOSITION_TOP],
            json!({"op": "share", "a": "sum.fossil.IT", "b": "total.IT"})
        );
        assert_eq!(
            spec["facts"]["lead1"]["filter"],
            json!({"geo": "IT", "siec": "TOTAL"})
        );
        let frame = crate::shape_registry::FRAMES
            .iter()
            .find(|(r, v, _)| (*r, *v) == (Relation::Composition, View::Slice))
            .unwrap()
            .2;
        assert_eq!(composition_kicker(Some(&fill)), Some(frame[0]));
        // the text step's label (field 1, the model's rewording) is the kicker, as on any page (q3 dropped it 7 of 7 runs
        // from 11-02 to 11-03: the composition words took the label's place); with no label the composition's words stand
        // where another page names its measure, never the first fetch's ranking measure
        let label = "各国发电结构";
        let (title, kicker) = title_and_kicker(Some(&fill), false, label, "发电总量");
        assert_eq!(
            (title.as_str(), kicker.as_str()),
            ("{name.IT}{name.fossil}占比最高，达{comp_top}", label)
        );
        let (title, kicker) = title_and_kicker(Some(&fill), false, "", "发电总量");
        assert_eq!(
            (title.as_str(), kicker.as_str()),
            ("{name.IT}{name.fossil}占比最高，达{comp_top}", frame[0])
        );
        let mut no_headline = fill.clone();
        no_headline.as_object_mut().unwrap().remove(HEADLINE);
        assert_eq!(
            title_and_kicker(Some(&no_headline), false, label, "发电总量"),
            (label.into(), frame[0].into())
        );
        assert_eq!(
            composition_kicker(Some(&json!({}))),
            None,
            "a page that is no composition keeps its own kicker"
        );
    }

    /// The text step's count of places is the distinct place codes (geo, a World Bank country) of the rows the fill's layers
    /// draw, a row only read left out; the ask carries it; a fill with no drawn row knows none.
    #[test]
    fn the_text_step_counts_the_places_the_fill_draws() {
        let row = |src: &str, dims: Value| json!({"src": src, "table": "t", "dims": dims, "time": "2024", "value": 1.0});
        let fill = json!({
            "rows": [row("a", json!({"geo": "DE", "siec": "C"})), row("b", json!({"geo": "DE", "siec": "G"})), row("c", json!({"geo": "FR"})),
                row("d", json!({"geo": "IT"})), row("e", json!({"country": "JPN"}))],
            "drawn": [{"layer": "bars", "src": "a"}, {"layer": "bars", "src": "b"}, {"layer": "bars", "src": "c"}, {"layer": "dots", "src": "e"}]});
        assert_eq!(places_drawn(&fill), Some(3));
        assert_eq!(
            places_drawn(&json!({"rows": fill["rows"], "drawn": []})),
            None
        );
        assert_eq!(places_drawn(&json!({"knobs": {}})), None);
        // with no drawn row, the places the hero's ranked names (a change page's bars), each a place of a row; a code no row
        // holds counts no place
        let ranked = json!({"rows": fill["rows"], "drawn": [], "knobs": {"spec": {"hero": {"data": {"ranked": ["DE", "FR", "XX"]}}}}});
        assert_eq!(places_drawn(&ranked), Some(2));
        let mut drafts = q1_drafts();
        drafts.places_drawn = places_drawn(&fill);
        let Ask::Text(text_ask) = drafts.ask(Vec::new()) else {
            unreachable!()
        };
        let TextAsk { places, .. } = *text_ask;
        assert_eq!(places, Some(3));
    }

    /// The text step's fields on a composition page hold none of the first fetch's total claims or its measure, only the
    /// composition's draft and its finding over share facts (scoped: the cut left places out); any other page's fields are
    /// drafted from its claims and charts as before.
    #[test]
    fn a_composition_page_s_text_step_reads_its_own_draft_not_the_total_claims() {
        let claims = vec![Claim {
            id: "c1".into(),
            kind: "rank_top".into(),
            template: "{first.geo} has the highest OBS VALUE in {first.year}: {first.value}."
                .into(),
        }];
        let charts = vec![Chart {
            relation: Relation::Ranking,
            view: View::Slice,
            claim_ids: vec!["c1".into()],
            category: "geo".into(),
            value: "value".into(),
        }];
        let page = Page {
            claims: claims.clone(),
            charts: charts.clone(),
            templates: Vec::new(),
            sentences: BTreeMap::new(),
            places: Vec::new(),
            times: vec!["2024".into()],
            measures: Vec::new(),
            plans: Vec::new(),
            scopes: vec![None],
        };
        let titles = vec!["发电总量".to_string()];
        let finding = json!({"dek": "{lead1.t}，{name.IT}{name.fossil}占比最高，为{comp_top}",
            "scoped": "{lead1.t}，图中各国中，{name.IT}{name.fossil}占比居首，为{comp_top}", "set": "图中各国中"});
        let fill = json!({"composition": {"bars": ["DE", "IT"], "dropped": [], "others": ["MT"], "left_out": []}, "finding": finding});
        let drafts = text_drafts(
            &page,
            page_lead(Some(&fill), &page.charts),
            &titles,
            Some(&fill),
            false,
        );
        let said: Vec<&str> = drafts
            .fields
            .iter()
            .map(|(_, t)| t.as_str())
            .chain(drafts.slots.iter().map(|(_, t)| t.as_str()))
            .collect();
        let all = said.join("\n");
        let ranking = crate::shape_registry::FRAMES
            .iter()
            .find(|(r, v, _)| (*r, *v) == (Relation::Ranking, View::Slice))
            .unwrap()
            .2;
        assert!(
            !all.contains("发电总量")
                && !all.contains("first.")
                && !ranking.iter().any(|w| all.contains(w)),
            "{all}"
        );
        assert!(
            drafts.slots.is_empty(),
            "no measure of the first fetch to name"
        );
        assert!(
            drafts.has_scope
                && all.contains("图中各国中，{name.IT}{name.fossil}占比居首，为{comp_top}"),
            "{all}"
        );
        let composition = crate::shape_registry::FRAMES
            .iter()
            .find(|(r, v, _)| (*r, *v) == (Relation::Composition, View::Slice))
            .unwrap()
            .2;
        assert!(composition.iter().any(|w| all.contains(w)), "{all}");
        // every bar drawn, none left out: unscoped
        let whole = json!({"composition": {"bars": ["DE", "IT"], "dropped": [], "others": [], "left_out": []}, "finding": finding});
        assert!(
            !text_drafts(
                &page,
                page_lead(Some(&whole), &page.charts),
                &titles,
                Some(&whole),
                false
            )
            .has_scope
        );
        // any other page: drafted from its claims and charts, as before
        let column = json!({"knobs": {"spec": {"hero": {}}}});
        let before = next_page::draft_for(
            &claims,
            &charts,
            Vec::new(),
            page_lead(Some(&column), &charts),
        )
        .name_measures(&titles, &charts)
        .with_scopes(&page.scopes)
        .with_finding(None)
        .with_periods(&page.times);
        assert_eq!(
            text_drafts(
                &page,
                page_lead(Some(&column), &charts),
                &titles,
                Some(&column),
                false
            ),
            before
        );
        assert_eq!(
            text_drafts(&page, page_lead(None, &charts), &titles, None, false),
            before
        );
    }

    /// A place the question names is never left out of a composition, read by code, not by name: a question that names Greece
    /// (the knowledge group reads it GR, by iso) stops a page that left out Eurostat's EL, whatever either name table calls it;
    /// a country the page kept, or a region, stops nothing.
    #[test]
    fn a_left_out_place_the_question_names_stops_the_page_by_its_code() {
        use crate::l5geo::Place;
        let fill = json!({"composition": {"dropped": ["EL", "PT"]}});
        assert!(named_dropped(&fill, &[Place::Country("GR".into())])
            .unwrap_err()
            .contains("EL"));
        assert!(named_dropped(&fill, &[Place::Country("PT".into())])
            .unwrap_err()
            .contains("PT"));
        assert!(named_dropped(&fill, &[Place::Country("CZ".into()), Place::Region]).is_ok());
        assert!(
            named_dropped(&json!({}), &[Place::Country("GR".into())]).is_ok(),
            "a page that is no composition left none out"
        );
    }

    /// The q6 shape (asylum applicants by citizenship into the EU, one year) in registry order: the ring refuses it for its
    /// one year, the column page is the first recipe that reads it, its place the citizenship; the flow page wants a flow.
    #[test]
    fn a_one_year_table_across_citizenships_is_a_column_page_and_never_a_ring() {
        let fixed = [
            ("freq", "A"),
            ("unit", "PER"),
            ("sex", "T"),
            ("age", "TOTAL"),
            ("geo", "EU27_2020"),
        ];
        let main = ring_rows(
            "migr",
            &fixed,
            ("citizen", &["SY", "AF", "UA", "TOTAL"]),
            &["2025"],
        );
        let tables = [("migr", &main[..])];
        let got: Vec<(&str, Result<String, String>)> = Hubs
            .recipes()
            .iter()
            .map(|r| {
                (
                    r.name.as_str(),
                    shape_of(&r.eats, &tables, &Hubs)
                        .map(|s| format!("{} {} {}", s.place, s.unit, s.year)),
                )
            })
            .collect();
        assert_eq!(
            got,
            [
                ("scmp", Err("not this shape: main spans one year (2025)".to_string())),
                ("ring", Err("not this shape: main spans one year (2025)".to_string())),
                ("composition_steps", Err("not this shape: main migr asks no grouped total alone".to_string())),
                ("composition", Err("not this shape: main migr asks no grouped total alone".to_string())),
                ("page_story", Err("not this shape: main spans one year (2025)".to_string())),
                ("one_line", Err("not this shape: main spans one year (2025)".to_string())),
                ("change", Err("not this shape: main spans one year (2025)".to_string())),
                ("change_bars", Err("not this shape: main spans one year (2025)".to_string())),
                ("column", Ok("citizen PER 2025".to_string())),
                ("ranked_bars", Ok("citizen PER 2025".to_string())),
                ("flow", Err("not this shape: main migr has no registered flow".to_string())),
                ("block_ranks", Err("not this shape: main migr is one table; a page over blocks reads two or more".to_string()))
            ]
        );
    }

    /// q2's flow fetch as the run reads it (next_params fill of the flow split: each fuel leaf to each sector leaf of final
    /// use): the rows of nrg_bal_s DE 2024 (KTOE, the data_prepare fixture) at those pairs, as series rows of table `id`.
    fn q2_flow_rows(id: &str) -> Vec<Value> {
        let fixture = include_str!("../scripts/fixtures/data_prepare/nrg_bal_s_DE_2024.tsv");
        let leaves = |dim: &str| {
            next_params::flow_asked("nrg_bal_s", dim)
                .unwrap()
                .into_iter()
                .map(|p| p.code)
                .collect::<Vec<_>>()
        };
        let (fuels, sectors) = (leaves("siec"), leaves("nrg_bal"));
        fixture_rows(id, fixture, &|bal, siec| {
            sectors.iter().any(|s| s == bal) && fuels.iter().any(|f| f == siec)
        })
    }

    /// A data_prepare fixture's rows (nrg_bal, siec, value; DE 2024, KTOE) that `keep` takes, as series rows of table `id`.
    fn fixture_rows(id: &str, fixture: &str, keep: &dyn Fn(&str, &str) -> bool) -> Vec<Value> {
        fixture
            .lines()
            .filter(|l| !l.starts_with('#'))
            .skip(1)
            .filter_map(|l| {
                let f: Vec<&str> = l.split('\t').collect();
                keep(f[0], f[1]).then(|| {
                    json!({"src": format!("series:{id}/A.{}.{}.KTOE.DE:2024:OBS_VALUE", f[0], f[1]), "table": id,
                        "dims": {"freq": "A", "nrg_bal": f[0], "siec": f[1], "unit": "KTOE", "geo": "DE"}, "time": "2024", "value": f[2]})
                })
            })
            .collect()
    }

    /// q2 (德国能源从来源到各部门) on its flow fetch: the flow recipe reads the registered pair siec -> nrg_bal, one unit and one
    /// year, and its sankey node fills the picture by program rules, every one of the 77 registered pairs accounted for:
    /// nuclear heat's 7 the registry leaves out (estat-parts.tsv excluded_from FC_E: Eurostat flags them not applicable), never
    /// fetched, each in the ledger as excluded by registry and said in a line by its name; of the 70 asked for, the 32 rows
    /// above zero are flows, each width a series row; the 37 zero ones are left out of the picture, counted by a fact (each in
    /// the ledger with its series src) and said in one line under it, which names peat and oil shale, zero on every pair; the
    /// one pair of two held codes with no row (heat to transport) is left out, in the ledger as no row and counted in a line of
    /// its own.
    /// Each node's value is a fact the visual group sums from its rows (no reported total is fetched); the fuels and sectors
    /// under min_share (3%) merge into one other node per side, named under the picture; names come from the name table of
    /// each dimension; the unit is in the picture's head only, its words marked with their registry rows. The real leaf child
    /// draws it, the twins bake and check it, and the page is published with nothing dropped: notes_dropped passes, no zero
    /// flow, unrowed or excluded pair counting as a drop. A fuel the flow asks for whose rows are all gone is still dropped
    /// as no row.
    #[test]
    fn q2_s_flow_rows_fill_a_sankey_page_whose_every_number_is_a_sum_layer_1_computes() {
        let main = q2_flow_rows("nrg_bal_s");
        assert_eq!(main.len(), 69);
        let asked = |dim: &str| next_params::flow_asked("nrg_bal_s", dim).unwrap().len();
        assert_eq!(
            (
                next_params::flow_parts("nrg_bal_s", "siec").len() * asked("nrg_bal"),
                asked("siec") * asked("nrg_bal")
            ),
            (77, 70)
        );
        let flow = recipe("flow");
        assert_eq!(
            (flow.layers.as_slice(), flow.eats.as_slice()),
            (
                &["sankey".to_string()][..],
                &["official_flow".to_string(), "one_unit".to_string()][..]
            )
        );
        let shape = shape_of(&flow.eats, &[("nrg_bal_s", &main[..])], &Hubs).unwrap();
        assert_eq!(
            shape.flow,
            Some(("siec".to_string(), "nrg_bal".to_string()))
        );
        assert_eq!((shape.year.as_str(), shape.unit.as_str()), ("2024", "KTOE"));
        let picks = picks_of(&flow.picks, &shape, &main, &[]).unwrap();
        let mut fill = test_fill(
            flow,
            &shape,
            &picks,
            (&main, &[]),
            &Hubs,
            ("标题", "导语"),
            false,
        )
        .unwrap();
        assert_eq!(fill["order"], json!(["sankey"]));
        assert_eq!(fill["rows"].as_array().unwrap().len(), 69);
        assert!(fill.get("finding").is_none());
        let spec = &fill["knobs"]["spec"];
        let data = &spec["hero"]["leaves"]["sankey"];
        let flows = data["flows"].as_array().unwrap();
        assert_eq!(flows.len(), 32);
        let first = main.iter().find(|r| row_value(r) != Some(0.0)).unwrap();
        assert_eq!(
            flows[0],
            json!({"source": first["dims"]["siec"], "target": first["dims"]["nrg_bal"], "value": first["src"]})
        );
        let nodes: BTreeSet<&str> = data["node_text"]
            .as_object()
            .unwrap()
            .keys()
            .map(String::as_str)
            .collect();
        assert_eq!(
            nodes,
            BTreeSet::from([
                "G3000",
                "O4000XBIO",
                "RA000",
                "E7000",
                "H8000",
                "FC_IND_E",
                "FC_TRA_E",
                "FC_OTH_CP_E",
                "FC_OTH_HH_E"
            ])
        );
        assert_eq!(
            (
                data["node_text"]["G3000"].as_str(),
                data["node_text"]["FC_IND_E"].as_str()
            ),
            (Some("fact:from.G3000.n"), Some("fact:to.FC_IND_E.n"))
        );
        // under 3% of all the flows: three fuels and three sectors, each side merged; peat and oil shale flow zero only, so they
        // are neither a node nor a member (the leaf drops their flows)
        assert_eq!(
            data["other_source"]["members"],
            json!(["C0000X0350-0370", "C0350-0370", "W6100_6220"])
        );
        assert_eq!(
            data["other_target"]["members"],
            json!(["FC_OTH_AF_E", "FC_OTH_FISH_E", "FC_OTH_NSP_E"])
        );
        assert_eq!(data["other_source"]["value_text"], "fact:from_other.n");
        assert!(
            data["other_source"].get("value").is_none(),
            "no series holds the merged sum"
        );
        assert_eq!(data["other_target"]["name"], json!([{"w": "其他去向"}]));
        assert!(
            data.get("empty").is_none(),
            "nuclear heat is excluded by the registry, no empty node"
        );
        assert_eq!(data["title"], json!([{"src": "name:frames:flow"}]));
        assert_eq!(
            data["unit"],
            json!([{"src": "name:unit_short_zh:KTOE"}, {"w": FLOW_SUM_WORDS}])
        );
        assert!(data.get("footnote").is_none());
        assert_eq!(
            data["lines"],
            json!([
                [{"w": "另有 "}, {"src": "fact:zero_flows.n"}, {"w": " 个组合为零"}, {"w": "，其中"}, {"src": "name:zh_names:siec:P1000"},
                    {"w": "、"}, {"src": "name:zh_names:siec:S2000"}, {"w": "的各个组合均为零"}],
                [{"w": "另有 "}, {"src": "fact:unrowed_flows.n"}, {"w": " 个组合在数据中没有记录"}],
                [{"src": "name:zh_names:siec:N900H"}, {"w": "：欧盟统计局标为不适用，不计入终端使用"}]
            ])
        );
        for (src, text) in [
            ("name:frames:flow", "从来源到去向"),
            ("name:unit_short_zh:KTOE", "千吨油当量"),
        ] {
            assert_eq!(fill["knobs"]["named"][src], text);
        }
        // every registered pair is excluded or asked for, and every pair asked for is drawn, zero, unrowed or an empty node's
        let pairs = &fill["pairs"];
        assert_eq!(
            pairs,
            &json!({"registered": 77, "excluded": 7, "asked": 70, "drawn": 32, "zero": 37, "unrowed": 1, "of_empty": 0})
        );
        let sum = |keys: &[&str]| -> u64 { keys.iter().map(|k| pairs[*k].as_u64().unwrap()).sum() };
        assert_eq!(
            (
                sum(&["drawn", "zero", "unrowed", "of_empty"]),
                sum(&["asked", "excluded"])
            ),
            (70, 77)
        );
        assert_eq!(
            (data["source_kind"].as_str(), data["target_kind"].as_str()),
            (Some("siec"), Some("nrg_bal"))
        );
        let facts = spec["facts"].as_object().unwrap();
        // B1: the target side is every code the registry asks for, so its whole (to_total, its codes summed) and each drawn
        // node's share of it are declared; the source side leaves nuclear heat out (excluded), so it has none
        assert_eq!(facts.len(), 19, "{facts:?}");
        assert!(
            facts.get("from_total").is_none()
                && facts["to_total"]["filter"]["nrg_bal"]
                    .as_array()
                    .is_some_and(|c| c.len() == 7),
            "{}",
            facts["to_total"]
        );
        let shares: Vec<&String> = facts
            .keys()
            .filter(|k| k.starts_with("to_share."))
            .collect();
        assert_eq!(
            shares,
            [
                "to_share.FC_IND_E",
                "to_share.FC_OTH_CP_E",
                "to_share.FC_OTH_HH_E",
                "to_share.FC_TRA_E"
            ]
        );
        assert_eq!(
            facts["to_share.FC_TRA_E"],
            json!({"op": "share", "a": "to.FC_TRA_E", "b": "to_total", "fmt": "pct"})
        );
        let pairs_out: Vec<&Value> = facts[FLOW_EXCLUDED]["pairs"]
            .as_array()
            .unwrap()
            .iter()
            .collect();
        assert_eq!(
            (pairs_out.len(), pairs_out[0]),
            (7, &json!(["N900H", "FC_IND_E"]))
        );
        assert_eq!(
            facts[FLOW_ZEROS],
            json!({"op": "zeros", "table": "nrg_bal_s", "time": "2024", "fmt": "n"})
        );
        assert_eq!(facts[FLOW_UNROWED]["by"], json!(["siec", "nrg_bal"]));
        assert_eq!(
            facts[FLOW_UNROWED]["codes"][0].as_array().unwrap().len(),
            10,
            "the held fuels: N900H is never fetched"
        );
        assert_eq!(
            facts["from.G3000"],
            json!({"op": "value", "table": "nrg_bal_s", "filter": {"siec": "G3000"}, "time": "2024", "fmt": "ktoe"})
        );
        assert_eq!(
            facts["to_other"]["filter"],
            json!({"nrg_bal": ["FC_OTH_AF_E", "FC_OTH_FISH_E", "FC_OTH_NSP_E"]})
        );
        assert_eq!(
            spec["fmts"]["ktoe"],
            json!({"scale": 1, "dec": 2, "suffix": " 千吨油当量"})
        );
        // the unit is the picture's head alone; the year line reads the table and the year
        assert!(spec["hero"].get("unit").is_none());
        assert_eq!(
            spec["hero"]["data"],
            json!({"table": "nrg_bal_s", "year": "2024"})
        );
        assert_eq!(
            fill["knobs"]["named"]["name:zh_names:siec:G3000"],
            "名G3000"
        );
        assert_eq!(
            fill["knobs"]["named"]["name:zh_names:nrg_bal:FC_OTH_FISH_E"],
            "名FC_OTH_FISH_E"
        );
        assert_eq!(fill["knobs"]["labels"]["W6100_6220"], "名W6100_6220");
        assert_eq!(
            fill["knobs"]["named"]["name:zh_names:siec:N900H"],
            "名N900H"
        );
        let drawn: Vec<&str> = fill["drawn"]
            .as_array()
            .unwrap()
            .iter()
            .map(|d| d["layer"].as_str().unwrap())
            .collect();
        assert_eq!(
            (drawn.len(), drawn.iter().all(|l| *l == "sankey")),
            (32, true),
            "the zero rows are read, never printed"
        );

        let all: f64 = main.iter().filter_map(row_value).sum();
        let (dropped, html, checks) = flow_page(&mut fill, &|page| {
            // each side's node values add up to all the flows: the merged node is its members' sum, nothing counted twice
            for side in FLOW_NODES {
                let sum: f64 = page
                    .facts
                    .iter()
                    .filter(|f| {
                        f.key.starts_with(&format!("{side}.")) || f.key == format!("{side}_other")
                    })
                    .map(|f| f.v)
                    .sum();
                assert!((sum - all).abs() <= 1e-9 * all, "{side}: {sum} vs {all}");
            }
            let gas = page.facts.iter().find(|f| f.key == "from.G3000").unwrap();
            assert_eq!(gas.reads.len(), 7, "one row per sector leaf");
            let zeros = page.facts.iter().find(|f| f.key == FLOW_ZEROS).unwrap();
            // the count the page prints is the number of flows the fill picked out as zero
            assert_eq!((zeros.v, zeros.n, zeros.reads.len()), (37.0, Some(37), 37));
            let unrowed = page.facts.iter().find(|f| f.key == FLOW_UNROWED).unwrap();
            assert_eq!(
                (unrowed.v, unrowed.who.as_slice()),
                (1.0, &["H8000>FC_TRA_E".to_string()][..])
            );
            let count = |kind: &str| page.ledger.keys().filter(|k| k.starts_with(kind)).count();
            assert_eq!(
                page.ledger.get("norow:H8000>FC_TRA_E").map(String::as_str),
                Some(crate::next_facts::NOROW_TEXT)
            );
            assert_eq!(count(crate::next_facts::NOROW_SRC), 1);
            assert_eq!(count(crate::next_facts::ZERO_SRC), 37);
            assert!(zeros.reads.iter().all(|src| page
                .ledger
                .get(&format!("{}{src}", crate::next_facts::ZERO_SRC))
                .map(String::as_str)
                == Some("0")));
            // nuclear heat's 7 pairs: a kind of their own in the ledger, neither no row nor zero
            let excluded = page.facts.iter().find(|f| f.key == FLOW_EXCLUDED).unwrap();
            assert_eq!((excluded.v, excluded.reads.len()), (7.0, 0));
            assert_eq!(count(crate::next_facts::EXCLUDED_SRC), 7);
            assert_eq!(
                page.ledger
                    .get("excluded:N900H>FC_TRA_E")
                    .map(String::as_str),
                Some(crate::next_facts::EXCLUDED_TEXT)
            );
            assert!(!page
                .ledger
                .keys()
                .any(|k| k.contains("N900H>") && !k.starts_with(crate::next_facts::EXCLUDED_SRC)));
        });
        assert!(
            html.contains(r#"<g data-layer="sankey">"#),
            "the sankey is the page's main layer"
        );
        for src in [
            "fact:from.G3000.r",
            "fact:to_other.r",
            "name:zh_names:siec:G3000",
            "name:zh_names:nrg_bal:FC_OTH_NSP_E",
        ] {
            assert!(html.contains(&format!(r#"data-src="{src}""#)), "{src}");
        }
        assert!(
            html.contains("其他来源包括：") && html.contains(FLOW_SUM_WORDS),
            "the members and the footnote are said"
        );
        assert!(
            html.contains(r#"data-src="fact:zero_flows.n">37</tspan> 个组合为零"#),
            "the zero flows are counted under the picture"
        );
        assert!(
            html.contains(r#"data-src="name:zh_names:siec:P1000""#),
            "a code zero on every pair is named"
        );
        assert!(
            html.contains(r#"data-src="fact:unrowed_flows.n">1</tspan> 个组合在数据中没有记录"#),
            "the unrowed pair is counted"
        );
        assert!(html.contains(r#"data-src="name:zh_names:siec:N900H">名N900H</tspan>：欧盟统计局标为不适用，不计入终端使用"#), "the excluded code is said");
        // nothing is dropped: the zero flows (peat's and oil shale's among them), the unrowed pair and nuclear heat's
        // excluded pairs are data or registry, so notes_dropped passes
        assert_eq!(dropped, []);
        let notes = checks.iter().find(|c| c.name == "notes_dropped").unwrap();
        assert_eq!((notes.passed, &notes.measured["items"]), (true, &json!([])));
        assert!(
            checks
                .iter()
                .find(|c| c.name == "same_numbers_twice")
                .unwrap()
                .passed
        );

        // a fuel the flow asks for with no row left at all (peat's rows gone) is still an empty node, dropped as no row
        let no_peat: Vec<Value> = main
            .iter()
            .filter(|r| r["dims"]["siec"] != "P1000")
            .cloned()
            .collect();
        let shape = shape_of(&flow.eats, &[("nrg_bal_s", &no_peat[..])], &Hubs).unwrap();
        let mut fill = test_fill(
            flow,
            &shape,
            &picks,
            (&no_peat, &[]),
            &Hubs,
            ("标题", "导语"),
            false,
        )
        .unwrap();
        assert_eq!(
            fill["knobs"]["spec"]["hero"]["leaves"]["sankey"]["empty"],
            json!({"source": ["P1000"]})
        );
        assert_eq!(fill["pairs"]["of_empty"], 7);
        let (dropped, _, checks) = flow_page(&mut fill, &|_| {});
        assert_eq!(
            dropped,
            [("dropped:sankey:P1000".to_string(), "no row".to_string())]
        );
        assert!(
            !checks
                .iter()
                .find(|c| c.name == "notes_dropped")
                .unwrap()
                .passed
        );
    }

    /// A flow fill as the run makes its page: its words set, the real leaf child fills it (`check` reads that page, its facts
    /// and ledger), the twins bake and check it, and it is published. What the layers dropped, the html and the page checks.
    fn flow_page(
        fill: &mut Value,
        check: &dyn Fn(&crate::next_visual::LeafFill),
    ) -> (Vec<(String, String)>, String, Vec<PageCheck>) {
        page_words(fill, ("标题", "导语", "栏目"));
        fill["knobs"]["spec"]["source"] = json!("来源");
        let order: Vec<String> = fill["order"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|l| l.as_str().map(str::to_string))
            .collect();
        let calls = std::sync::Mutex::new(Vec::new());
        let request = crate::next_visual::Request::LeafFill {
            recipe: "flow",
            rows: fill["rows"].as_array().unwrap(),
            knobs: &fill["knobs"],
            order: &order,
            runtime: Path::new("runtime"),
        };
        let page = match crate::next_flow::visual_call(&calls, "leaf_fill", request) {
            Ok(crate::next_visual::Reply::Filled(page)) => page,
            Ok(_) => panic!("not a filled page"),
            Err(e) => panic!("leaf fill: {e}"),
        };
        check(&page);
        let dir = tempfile::tempdir().unwrap();
        let bundle = {
            let _command = crate::group_guard::command_for_test("investigate");
            crate::artifact::InvestigationBundle::create(dir.path(), "leaf page").unwrap()
        };
        let _command = crate::group_guard::command_for_test("investigate");
        let _doors = crate::group_guard::doors_for_test(true);
        let bake = crate::next_leaf::Runner::python(Path::new("fixtures/next_leaf/bake_twin.py"));
        let mut qa = crate::next_leaf::Runner::python(Path::new("fixtures/next_visual/qa_twin.py"));
        qa.args.push("pass".into());
        let leaf = crate::next_visual::LeafPage {
            draw: &page.draw,
            bake: &bake,
            w: page.w,
            h: page.h,
            frame: page.frame.clone(),
            layers: &page.layers,
            ledger: &page.ledger,
            refs: &page.refs,
            facts: (&page.spec, &page.rows, &page.facts),
            strip: None,
            hero: None,
        };
        let plan = json!({"kind": "leaf_plan", "recipe": "flow"});
        let published =
            crate::next_flow::publish_leaf_page(&calls, &bundle.dir, "flow", (&leaf, &plan), &qa)
                .unwrap();
        let html = std::fs::read_to_string(bundle.dir.join(&published.html_ref)).unwrap();
        let checks = page_checks(
            recipe("flow"),
            Some(html.as_str()),
            &published.dropped,
            StripAsk::default(),
            fill["drawn"].as_array().unwrap(),
            None,
        );
        (published.dropped, html, checks)
    }

    /// Hubs, but the name table names no code of `scheme`.
    struct NoNamesOf(&'static str);
    impl Catalogue for NoNamesOf {
        fn top5(
            &self,
            _: &str,
            _: &[String],
            _: bool,
            _: Option<i32>,
            _: Option<i32>,
        ) -> crate::l5geo::Ranking {
            unreachable!()
        }
        fn places_outside(&self, _: &str, _: &[String]) -> Vec<String> {
            unreachable!()
        }
        fn source(&self) -> &Value {
            &Value::Null
        }
        fn countries(&self, codes: &[String]) -> Result<Vec<String>, String> {
            Hubs.countries(codes)
        }
        fn zh_names(
            &self,
            scheme: &str,
            codes: &[String],
        ) -> Result<BTreeMap<String, String>, Vec<String>> {
            if scheme == self.0 {
                Err(codes.to_vec())
            } else {
                Hubs.zh_names(scheme, codes)
            }
        }
        fn members(&self, aggregate: &str) -> Result<Vec<String>, String> {
            Hubs.members(aggregate)
        }
    }

    /// The flow shape takes any registered flow table, not one picture's: nrg_bal_c (the family's other table) on the same
    /// rows fills the same nodes; a side of one code (nrg_bal_c's FC_E rows by fuel, its sector rows at siec TOTAL), a total or
    /// a subtotal beside the leaves, another varying dimension, two years and a table with no registered flow are refused by
    /// name. A side with one small node merges none; a dimension the name table names nothing of refuses the fill.
    #[test]
    fn the_flow_shape_takes_any_registered_flow_table_and_refuses_what_is_no_flow_by_name() {
        let flow = recipe("flow");
        let shape_for = |id: &str, rows: &[Value]| shape_of(&flow.eats, &[(id, rows)], &Hubs);
        let filled = |id: &str, rows: &[Value], catalogue: &dyn Catalogue| {
            let shape = shape_for(id, rows).unwrap();
            test_fill(
                flow,
                &shape,
                &Picks::default(),
                (rows, &[]),
                catalogue,
                ("标题", "导语"),
                false,
            )
        };
        let nodes = |fill: &Value| -> Vec<String> {
            fill["knobs"]["spec"]["hero"]["leaves"]["sankey"]["node_text"]
                .as_object()
                .unwrap()
                .keys()
                .cloned()
                .collect()
        };
        let (c, s) = (q2_flow_rows("nrg_bal_c"), q2_flow_rows("nrg_bal_s"));
        let of_c = filled("nrg_bal_c", &c, &Hubs).unwrap();
        assert_eq!(
            nodes(&of_c),
            nodes(&filled("nrg_bal_s", &s, &Hubs).unwrap())
        );
        assert_eq!(
            of_c["knobs"]["spec"]["facts"][FLOW_ZEROS]["table"],
            "nrg_bal_c"
        );
        assert_eq!(
            of_c["knobs"]["spec"]["hero"]["leaves"]["sankey"]["flows"]
                .as_array()
                .unwrap()
                .len(),
            32
        );
        let no = |id: &str, rows: &[Value]| shape_for(id, rows).unwrap_err();
        let fc_e = include_str!("../scripts/fixtures/data_prepare/nrg_bal_c_DE_2024_FC_E.tsv");
        let fuels: Vec<String> = next_params::flow_parts("nrg_bal_c", "siec")
            .into_iter()
            .map(|p| p.code)
            .collect();
        let by_fuel = fixture_rows("nrg_bal_c", fc_e, &|_, siec| {
            fuels.iter().any(|f| f == siec)
        });
        assert_eq!(no("nrg_bal_c", &by_fuel), "not this shape: main nrg_bal_c holds 1 nrg_bal code(s), and a flow's side holds two or more");
        let every_fuel = fixture_rows("nrg_bal_c", fc_e, &|_, _| true);
        assert!(
            no("nrg_bal_c", &every_fuel).contains("which is no registered leaf of it"),
            "{}",
            no("nrg_bal_c", &every_fuel)
        );
        let total = include_str!("../scripts/fixtures/data_prepare/nrg_bal_c_DE_2024_TOTAL.tsv");
        let by_sector = fixture_rows("nrg_bal_c", total, &|bal, _| bal != "FC_E");
        assert_eq!(no("nrg_bal_c", &by_sector), "not this shape: main nrg_bal_c holds 1 siec code(s), and a flow's side holds two or more");
        // a subtotal beside its own parts would count them twice
        let mut other = s.clone();
        let mut row = s[0].clone();
        row["dims"]["nrg_bal"] = json!("FC_OTH_E");
        row["src"] = json!("series:nrg_bal_s/A.FC_OTH_E.x.KTOE.DE:2024:OBS_VALUE");
        other.push(row);
        assert_eq!(no("nrg_bal_s", &other), "not this shape: main nrg_bal_s holds nrg_bal FC_OTH_E, which is no registered leaf of it");
        let mut two_places = s.clone();
        let mut fr = s[0].clone();
        fr["dims"]["geo"] = json!("FR");
        fr["src"] = json!("series:nrg_bal_s/fr:2024:OBS_VALUE");
        two_places.push(fr);
        assert_eq!(
            no("nrg_bal_s", &two_places),
            "not this shape: main geo varies beside the flow from siec to nrg_bal"
        );
        let mut two_years = s.clone();
        let mut later = s[0].clone();
        later["time"] = json!("2023");
        later["src"] = json!("series:nrg_bal_s/x:2023:OBS_VALUE");
        two_years.push(later);
        assert_eq!(
            no("nrg_bal_s", &two_years),
            r#"not this shape: main nrg_bal_s spans ["2023", "2024"], and a flow is one year"#
        );
        assert_eq!(
            no("nrg_x", &q2_flow_rows("nrg_x")),
            "not this shape: main nrg_x has no registered flow"
        );
        // one fuel under min_share is no merge (an other node takes two or more): it is drawn as its own node
        let pairs = [
            ("FC_IND_E", "G3000", "100"),
            ("FC_TRA_E", "G3000", "50"),
            ("FC_IND_E", "E7000", "60"),
            ("FC_TRA_E", "H8000", "1"),
        ];
        let small: Vec<Value> = pairs
            .iter()
            .map(|(bal, siec, v)| json!({"src": format!("series:nrg_bal_s/{bal}.{siec}:2024:OBS_VALUE"), "table": "nrg_bal_s",
                "dims": {"freq": "A", "nrg_bal": bal, "siec": siec, "unit": "KTOE", "geo": "DE"}, "time": "2024", "value": v}))
            .collect();
        let fill = filled("nrg_bal_s", &small, &Hubs).unwrap();
        let data = &fill["knobs"]["spec"]["hero"]["leaves"]["sankey"];
        assert_eq!(
            nodes(&fill),
            ["E7000", "FC_IND_E", "FC_TRA_E", "G3000", "H8000"]
        );
        assert!(data.get("other_source").is_none() && data.get("other_target").is_none());
        assert_eq!(data["empty"]["target"].as_array().unwrap().len(), 5);
        assert_eq!(fill["knobs"]["spec"]["fmts"]["ktoe"]["dec"], 0);
        // no flow of 0: nothing to count; the two pairs of held codes with no row (electricity to transport, heat to industry)
        // are counted in their own line
        assert!(fill["knobs"]["spec"]["facts"].get(FLOW_ZEROS).is_none());
        assert_eq!(
            data["lines"],
            json!([[{"w": "另有 "}, {"src": "fact:unrowed_flows.n"}, {"w": " 个组合在数据中没有记录"}],
                [{"src": "name:zh_names:siec:N900H"}, {"w": FLOW_EXCLUDED_WORDS}]])
        );
        // the fuels with no row are empty, nuclear heat (excluded by the registry) not among them
        assert_eq!(data["empty"]["source"].as_array().unwrap().len(), 7);
        assert!(!data["empty"]["source"]
            .as_array()
            .unwrap()
            .contains(&json!("N900H")));
        assert_eq!(
            fill["pairs"],
            json!({"registered": 77, "excluded": 7, "asked": 70, "drawn": 4, "zero": 0, "unrowed": 2, "of_empty": 64})
        );
        // the second shape reads the registry's exclusion too: nrg_bal_c's fill leaves nuclear heat out the same way
        assert_eq!(
            of_c["pairs"],
            json!({"registered": 77, "excluded": 7, "asked": 70, "drawn": 32, "zero": 37, "unrowed": 1, "of_empty": 0})
        );
        assert_eq!(
            of_c["knobs"]["spec"]["facts"][FLOW_EXCLUDED]["table"],
            "nrg_bal_c"
        );
        // a main that holds an excluded code is refused by name
        let mut nuclear = s.clone();
        let mut row = s[0].clone();
        row["dims"]["siec"] = json!("N900H");
        row["src"] = json!("series:nrg_bal_s/A.FC_IND_E.N900H.KTOE.DE:2024:OBS_VALUE");
        nuclear.push(row);
        assert_eq!(no("nrg_bal_s", &nuclear), "not this shape: main nrg_bal_s holds siec N900H, which the registry leaves out of the flow");
        // no Chinese name for a fuel: the fill refuses, naming the codes, never printing a code or an English name
        let why = filled("nrg_bal_s", &small, &NoNamesOf("siec")).unwrap_err();
        assert_eq!(why, "not this shape: sankey: the name table gives no Chinese name for siec G3000, E7000, H8000, N900H");
    }

