    /// q2's flow page passes the name step on the reviewed code names (code-names-zh.json): every fuel and sector it names
    /// (drawn nodes, merged members, the codes zero on every pair and the code the registry leaves out) is the reviewed short
    /// name, marked with its name row.
    #[test]
    fn q2_s_flow_page_takes_every_name_from_the_reviewed_code_names() {
        let _command = crate::group_guard::command_for_test("investigate");
        let main = q2_flow_rows("nrg_bal_s");
        let flow = recipe("flow");
        let shape = shape_of(&flow.eats, &[("nrg_bal_s", &main[..])], &GroupNames).unwrap();
        let fill = test_fill(
            flow,
            &shape,
            &Picks::default(),
            (&main, &[]),
            &GroupNames,
            ("标题", "导语"),
            false,
        )
        .unwrap();
        let named = fill["knobs"]["named"].as_object().unwrap();
        for (src, zh) in [
            ("name:zh_names:siec:G3000", "天然气"),
            ("name:zh_names:siec:P1000", "泥炭"),
            ("name:zh_names:siec:N900H", "核热"),
            ("name:zh_names:nrg_bal:FC_OTH_CP_E", "商业公服"),
        ] {
            assert_eq!(named[src], zh, "{src}");
        }
        let codes = named
            .keys()
            .filter(|k| {
                k.starts_with("name:zh_names:siec:") || k.starts_with("name:zh_names:nrg_bal:")
            })
            .count();
        assert_eq!(codes, 18, "10 fuels with a row, nuclear heat (said as excluded) and 7 sector leaves, every one named: {named:?}");
    }

    /// A fetched flow (classify's official pair siec -> nrg_bal, both varying) is ranked against the flow recipe's sankey
    /// alone, so the charts step keeps the table, its chart's category the claims' one entity column; the same series with no
    /// official pair is ranked against the filled templates and never gets the sankey.
    #[test]
    fn a_fetched_flow_series_is_ranked_against_the_sankey_alone_and_takes_its_entity_column() {
        use crate::shape_registry::{Role, VaryingDim};
        let _command = crate::group_guard::command_for_test("investigate");
        let dim = |d: &str, n: usize, role: Role| VaryingDim {
            dim: d.into(),
            members: n,
            roles: vec![role, Role::Category],
            is_place: false,
            iso_countries: false,
            total_member: None,
        };
        let shape = crate::shape_registry::Shape {
            dims: vec![
                dim("siec", 10, Role::FlowSource),
                dim("nrg_bal", 7, Role::FlowTarget),
            ],
            unit_additive: true,
            official_flow: Some(("siec".into(), "nrg_bal".into())),
        };
        let series = json!({"columns": ["name", "value", "year"], "rows": [{"name": "G3000 / FC_IND_E", "value": 12046.5, "year": 2024},
            {"name": "E7000 / FC_IND_E", "value": 17580.1, "year": 2024}]});
        let picked = Picked {
            claim: Claim {
                id: "c1".into(),
                kind: "rank_top".into(),
                template: String::new(),
            },
            own: json!({"rows": [{}]}),
            series,
        };
        let table = Prepared {
            id: "nrg_bal_s".into(),
            title: String::new(),
            file: String::new(),
            args: Map::new(),
            sheet: String::new(),
            claims: Vec::new(),
            places_zh: Vec::new(),
            companions: Vec::new(),
            chain: Vec::new(),
            asked: json!([]),
            relation: None,
        };
        let (drawn, event) =
            group_charts(&shape, &table, &Hubs, &[], View::Slice, &[&picked], true).unwrap();
        assert_eq!(event["template"], "sankey");
        let chart = &drawn[0].chart;
        assert_eq!(
            (
                chart.relation,
                chart.category.as_str(),
                chart.value.as_str()
            ),
            (Relation::Flow, "name", "value")
        );
        assert_eq!(template_of(chart, "c1", None)["chart_type"], "sankey");
        let plain = crate::shape_registry::Shape {
            official_flow: None,
            ..shape.clone()
        };
        if let Ok((_, event)) =
            group_charts(&plain, &table, &Hubs, &[], View::Slice, &[&picked], true)
        {
            assert_ne!(event["template"], "sankey");
        }
    }

    fn recipe_like(r: &Recipe) -> Recipe {
        Recipe {
            name: r.name.clone(),
            layers: r.layers.clone(),
            eats: r.eats.clone(),
            charts: r.charts.clone(),
            picks: r.picks.clone(),
            exposes: r.exposes.clone(),
            window: r.window.clone(),
            same_measure: r.same_measure.clone(),
            strip: r.strip,
            opening: r.opening,
            external: r.external.clone(),
            points: r.points.clone(),
            short_notes: r.short_notes.clone(),
            relation: r.relation.clone(),
            blocks_only: r.blocks_only,
            without: r.without.clone(),
        }
    }

    /// The gas fixture's ring page drawn, baked and checked by the leaf children (env as ring_fill_of_the_gas_fixture; run with
    /// --ignored): the visual group's LeafPage on its LeafFill, nothing written or published; prints each layer's record (its
    /// milliseconds) or the first refusal, for the draw stage's measurement.
    #[test]
    #[ignore]
    fn the_gas_ring_page_through_the_leaf_children() {
        gas_ring_page(None);
    }

    /// The gas ring page narrowed (owner 11-03: a narrowed ring page keeps its headline, its set named with the map's count
    /// of the places it compares): the fixture's 167 partners cut to the origins the map compares at t1, the set's members
    /// that count; the page keeps its finding and headline, its set the map's drawn, and is drawn and rechecked whole.
    #[test]
    #[ignore]
    fn the_gas_ring_page_narrowed_keeps_its_headline() {
        let fill = gas_ring_page(Some(8));
        assert!(
            fill[HEADLINE].is_object() && fill.get(FELL_BACK).is_none(),
            "{}",
            fill[HEADLINE]
        );
        assert_eq!(fill["finding"]["set"], json!("在本指标最高的{drawn}项中"));
    }

    /// The gas ring page through the leaf children (as the_gas_scmp_page_through_the_leaf_children): the ring recipe's
    /// fill, its LeafFill, the page drawn, baked and rechecked; `members`: the page narrowed to a set of that many places
    /// (its words the scope's). Prints each layer's record or the first refusal; LEAF_PAGE_OUT: where to write the page.
    fn gas_ring_page(members: Option<usize>) -> Value {
        let (main, monthly, catalogue, _, claims) = gas_fixture();
        let ring = recipe(RING_RECIPE);
        let shape = shape_of(
            &ring.eats,
            &[("nrg_ti_gas", &main), ("nrg_ti_gasm", &monthly)],
            &catalogue,
        )
        .unwrap();
        let picks = picks_of(&ring.picks, &shape, &main, &claims).unwrap();
        // narrowed: the main's rows cut to the `members` origins largest at t1 (as the scope's narrowing keeps its places), the
        // members' and aggregates' rows kept, and the page's shape and picks read again over the cut
        let (main, shape, picks) = match members {
            None => (main, shape, picks),
            Some(n) => {
                let at = |c: &str| {
                    main.iter()
                        .filter(|r| {
                            r["dims"][&shape.place] == c
                                && r["dims"]["geo"] == shape.hub.as_str()
                                && r["time"] == picks.t1.as_str()
                        })
                        .find_map(row_value)
                        .unwrap_or(0.0)
                };
                let mut ranked: Vec<(f64, &String)> =
                    shape.outside.iter().map(|c| (at(c), c)).collect();
                ranked.sort_by(|a, b| b.0.total_cmp(&a.0));
                let keep: Vec<&String> = ranked.iter().take(n).map(|(_, c)| *c).collect();
                println!(
                    "narrowed: {} of {} origins: {keep:?}",
                    keep.len(),
                    shape.outside.len()
                );
                let cut: Vec<Value> = main
                    .iter()
                    .filter(|r| {
                        r["dims"][&shape.place].as_str().is_none_or(|c| {
                            !shape.outside.iter().any(|o| o == c) || keep.iter().any(|k| *k == c)
                        })
                    })
                    .cloned()
                    .collect();
                let shape = shape_of(
                    &ring.eats,
                    &[("nrg_ti_gas", &cut), ("nrg_ti_gasm", &monthly)],
                    &catalogue,
                )
                .unwrap();
                let picks = picks_of(&ring.picks, &shape, &cut, &claims).unwrap();
                (cut, shape, picks)
            }
        };
        let set = members.map(|n| json!({"words": "在本指标最高的{n}项中", "members": n}));
        let mut fill = test_fill_set(
            ring,
            &shape,
            &picks,
            (&main, &monthly),
            &catalogue,
            ("标题", "导语"),
            set.is_some(),
            set,
        )
        .unwrap();
        println!(
            "ring finding {} headline {} set {}",
            fill["finding"]["dek"], fill[HEADLINE]["title"], fill["finding"]["set"]
        );
        fill["knobs"]["shapes"] = json!("runtime/pi/assets/naturalearth-admin0-50m.geojson");
        fill["knobs"]["spec"]["kicker"] = json!("栏目");
        fill["knobs"]["spec"]["source"] = json!("欧盟统计局 nrg_ti_gas、nrg_ti_gasm");
        let order: Vec<String> = fill["order"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|l| l.as_str().map(str::to_string))
            .collect();
        let calls = std::sync::Mutex::new(Vec::new());
        let request = crate::next_visual::Request::LeafFill {
            recipe: RING_RECIPE,
            rows: fill["rows"].as_array().unwrap(),
            knobs: &fill["knobs"],
            order: &order,
            runtime: Path::new("runtime"),
        };
        let page = match crate::next_flow::visual_call(&calls, "leaf_fill", request) {
            Ok(crate::next_visual::Reply::Filled(page)) => page,
            Ok(_) => panic!("not a filled page"),
            Err(e) => panic!("leaf fill: {e}"),
        };
        let leaf = crate::next_visual::LeafPage {
            draw: &page.draw,
            bake: &page.bake,
            w: page.w,
            h: page.h,
            frame: page.frame.clone(),
            layers: &page.layers,
            ledger: &page.ledger,
            refs: &page.refs,
            facts: (&page.spec, &page.rows, &page.facts),
            strip: None,
            hero: None,
        };
        let started = std::time::Instant::now();
        match crate::next_flow::visual_call(
            &calls,
            "leaf_page",
            crate::next_visual::Request::LeafPage { page: &leaf },
        ) {
            Ok(crate::next_visual::Reply::Leaf(drawn)) => {
                for r in &drawn.records {
                    println!("record {} {} {} ms {}", r.node, r.layer, r.outcome, r.ms);
                }
                println!(
                    "drawn page {} bytes ms {}",
                    drawn.html.len(),
                    started.elapsed().as_millis()
                );
                if let Ok(out) = std::env::var("LEAF_PAGE_OUT") {
                    std::fs::write(out, &drawn.html).unwrap();
                }
                // the visual group's recheck of the page as drawn: its references' lines, its months split by the years
                let recheck = crate::next_visual::Request::LeafRecheck {
                    recipe: RING_RECIPE,
                    html: &drawn.html,
                    ledger: leaf.ledger,
                    refs: leaf.refs,
                    facts: leaf.facts,
                    knobs: &drawn.knobs,
                };
                match crate::next_flow::visual_call(&calls, "leaf_recheck", recheck) {
                    Ok(crate::next_visual::Reply::Rechecked(off)) => {
                        println!("recheck {} finding(s): {off:?}", off.len());
                        assert!(off.is_empty(), "the ring page's recheck: {off:?}");
                    }
                    other => panic!("recheck: {:?}", other.err()),
                }
            }
            Ok(_) => panic!("not a leaf page"),
            Err(why) => {
                println!("refused ms {}: {why}", started.elapsed().as_millis());
                if let Err((records, _)) = crate::next_leaf::draw_page(
                    leaf.draw,
                    leaf.w,
                    leaf.h,
                    leaf.frame.clone(),
                    leaf.layers,
                ) {
                    for r in &records {
                        println!("record {} {} {} ms {}", r.node, r.layer, r.outcome, r.ms);
                    }
                }
                // a measurement: the first refusal is printed (stuck), not asserted
                println!("stuck: {why}");
            }
        };
        fill
    }

    /// The gas fixture's scmp page (env as ring_fill_of_the_gas_fixture; run with --ignored): the scmp recipe's shape, picks and
    /// fill over the fixture, its LeafFill, then the page drawn and baked by the leaf children from this tree's runtime/ (the
    /// visual group's LeafPage), nothing written or published; prints the fill's sizes, each layer's record (its
    /// milliseconds) or the first refusal, for the measurement; LEAF_PAGE_OUT: where to write the page.
    #[test]
    #[ignore]
    fn the_gas_scmp_page_through_the_leaf_children() {
        let started = std::time::Instant::now();
        let (main, monthly, catalogue, _, claims) = gas_fixture();
        let scmp = recipe("scmp");
        let shape = shape_of(
            &scmp.eats,
            &[("nrg_ti_gas", &main), ("nrg_ti_gasm", &monthly)],
            &catalogue,
        )
        .unwrap();
        let picks = picks_of(&scmp.picks, &shape, &main, &claims).unwrap();
        let mut fill = test_fill(
            scmp,
            &shape,
            &picks,
            (&main, &monthly),
            &catalogue,
            ("标题", "导语"),
            false,
        )
        .unwrap();
        fill["knobs"]["shapes"] = json!("runtime/pi/assets/naturalearth-admin0-50m.geojson");
        fill["knobs"]["spec"]["kicker"] = json!("栏目");
        fill["knobs"]["spec"]["source"] = json!("欧盟统计局 nrg_ti_gas、nrg_ti_gasm");
        let hero = &fill["knobs"]["spec"]["hero"];
        println!(
            "scmp fill order {} rows {} facts {} notes {} bignums {} strip from {} ms {}",
            fill["order"],
            fill["rows"].as_array().unwrap().len(),
            fill["knobs"]["spec"]["facts"].as_object().unwrap().len(),
            hero["leaves"]["notes"]["notes"]
                .as_array()
                .map_or(0, Vec::len),
            hero["data"]["bignums"],
            hero["strip"]["from"],
            started.elapsed().as_millis()
        );
        let order: Vec<String> = fill["order"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|l| l.as_str().map(str::to_string))
            .collect();
        let calls = std::sync::Mutex::new(Vec::new());
        let request = crate::next_visual::Request::LeafFill {
            recipe: "scmp",
            rows: fill["rows"].as_array().unwrap(),
            knobs: &fill["knobs"],
            order: &order,
            runtime: Path::new("runtime"),
        };
        let page = match crate::next_flow::visual_call(&calls, "leaf_fill", request) {
            Ok(crate::next_visual::Reply::Filled(page)) => page,
            Ok(_) => panic!("not a leaf fill"),
            Err(why) => panic!("stuck scmp-fill: {why}"),
        };
        let leaf = crate::next_visual::LeafPage {
            draw: &page.draw,
            bake: &page.bake,
            w: page.w,
            h: page.h,
            frame: page.frame.clone(),
            layers: &page.layers,
            ledger: &page.ledger,
            refs: &page.refs,
            facts: (&page.spec, &page.rows, &page.facts),
            strip: None,
            hero: None,
        };
        let started = std::time::Instant::now();
        match crate::next_flow::visual_call(
            &calls,
            "leaf_page",
            crate::next_visual::Request::LeafPage { page: &leaf },
        ) {
            Ok(crate::next_visual::Reply::Leaf(drawn)) => {
                for r in &drawn.records {
                    println!("record {} {} {} ms {}", r.node, r.layer, r.outcome, r.ms);
                }
                println!(
                    "drawn page {} bytes ms {}",
                    drawn.html.len(),
                    started.elapsed().as_millis()
                );
                println!(
                    "type {}",
                    drawn
                        .type_measured
                        .as_ref()
                        .map_or("none".to_string(), Value::to_string)
                );
                if let Ok(out) = std::env::var("LEAF_PAGE_OUT") {
                    std::fs::write(out, &drawn.html).unwrap();
                }
                // the visual group's recheck of the page as drawn (its references' legend lines among it)
                let recheck = crate::next_visual::Request::LeafRecheck {
                    recipe: "scmp",
                    html: &drawn.html,
                    ledger: leaf.ledger,
                    refs: leaf.refs,
                    facts: leaf.facts,
                    knobs: &drawn.knobs,
                };
                match crate::next_flow::visual_call(&calls, "leaf_recheck", recheck) {
                    Ok(crate::next_visual::Reply::Rechecked(off)) => {
                        println!("recheck {} finding(s): {off:?}", off.len())
                    }
                    other => println!("recheck: {:?}", other.err()),
                }
            }
            Ok(_) => panic!("not a leaf page"),
            Err(why) => {
                println!("refused ms {}: {why}", started.elapsed().as_millis());
                // the page as drawn, before the bake, for a refusal past the draw (LEAF_PAGE_OUT with .drawn.html)
                let records = match crate::next_leaf::draw_page(
                    leaf.draw,
                    leaf.w,
                    leaf.h,
                    leaf.frame.clone(),
                    leaf.layers,
                ) {
                    Ok((_, html, records)) => {
                        if let Ok(out) = std::env::var("LEAF_PAGE_OUT") {
                            std::fs::write(format!("{out}.drawn.html"), html).unwrap();
                        }
                        records
                    }
                    Err((records, _)) => records,
                };
                for r in &records {
                    println!("record {} {} {} ms {}", r.node, r.layer, r.outcome, r.ms);
                }
            }
        };
    }

