    /// A World Bank indicator as the catalogue lists it: three countries (aggregates left out), the unit wb-units.tsv registers
    /// (`unit`, none when it has no row), or a table the catalogue does not list as World Bank's (`listed` false).
    struct WbTable {
        unit: Option<&'static str>,
        listed: bool,
    }

    impl Catalogue for WbTable {
        fn top5(
            &self,
            _: &str,
            _: &[String],
            _: bool,
            _: Option<i32>,
            _: Option<i32>,
        ) -> crate::l5geo::Ranking {
            unreachable!()
        }
        fn places_outside(&self, _: &str, _: &[String]) -> Vec<String> {
            unreachable!()
        }
        fn source(&self) -> &Value {
            &Value::Null
        }
        fn table(&self, id: &str) -> Option<crate::l5geo::TableMeta> {
            Some(crate::l5geo::TableMeta {
                id: id.into(),
                worldbank: self.listed,
                dims: Vec::new(),
                end_year: None,
                places: [("CN", "CHN"), ("IN", "IND"), ("US", "USA")]
                    .iter()
                    .map(|(i, c)| (i.to_string(), c.to_string()))
                    .collect(),
                place_members: Vec::new(),
                freqs: Vec::new(),
                unit: self.unit.map(|code| crate::l5geo::Unit {
                    code: code.into(),
                    label: String::new(),
                    kind: Some("rate"),
                }),
            })
        }
    }

    /// A World Bank main's series rows (next_knowledge series_rows: the one place dimension "country", codes as written, the
    /// aggregate WLD kept) take the column page's shape: the place is the country dimension, its countries the codes the
    /// catalogue lists among its countries (WLD is none), the unit the indicator's registered code, the year the last any
    /// country has a value at; the ranking ranks those countries only. No registered unit, or a table the catalogue does not
    /// list as World Bank's, is refused by name; Countries is never asked of World Bank codes.
    #[test]
    fn a_world_bank_main_takes_the_column_shape_with_its_registered_unit() {
        let id = "EN.GHG.CO2.PC.CE.AR5@2";
        let row = |place: &str, time: &str, value: &str| {
            json!({"src": format!("series:{id}/{place}:{time}:value"), "table": id, "dims": {"country": place},
                "time": time, "value": value})
        };
        let rows = vec![
            row("USA", "2024", "13.8"),
            row("USA", "2023", "14.1"),
            row("CHN", "2024", "9.2"),
            row("WLD", "2025", "4.7"),
            row("IND", "2024", "2.1"),
        ];
        let tables: Vec<(&str, &[Value])> = vec![(id, &rows)];
        let eats: Vec<String> = ["annual", "one_place", "one_unit", "last_year"]
            .map(String::from)
            .to_vec();
        let shape = shape_of(
            &eats,
            &tables,
            &WbTable {
                unit: Some("TCO2E_HAB"),
                listed: true,
            },
        )
        .unwrap();
        assert_eq!(
            (
                shape.place.as_str(),
                shape.countries.clone(),
                shape.unit.as_str(),
                shape.year.as_str()
            ),
            (
                "country",
                vec!["CHN".to_string(), "IND".into(), "USA".into()],
                "TCO2E_HAB",
                "2024"
            )
        );
        let picks = picks_of(&["ranked".to_string()], &shape, &rows, &[]).unwrap();
        assert_eq!(picks.ranked, ["USA", "CHN", "IND"]);
        assert!(
            next_pack::unit_short(&shape.unit).is_some(),
            "the fill's unit line has a row for it"
        );
        assert_eq!(
            shape_of(
                &eats,
                &tables,
                &WbTable {
                    unit: None,
                    listed: true
                }
            )
            .unwrap_err(),
            format!("not this shape: main {id} has no registered unit")
        );
        assert_eq!(
            shape_of(
                &eats,
                &tables,
                &WbTable {
                    unit: Some("TCO2E_HAB"),
                    listed: false
                }
            )
            .unwrap_err(),
            format!("not this shape: the catalogue lists no World Bank table {id}")
        );
        let ring: Vec<String> = ["annual", "years_2", "hub_origin"]
            .map(String::from)
            .to_vec();
        assert!(shape_of(
            &ring,
            &tables,
            &WbTable {
                unit: Some("TCO2E_HAB"),
                listed: true
            }
        )
        .is_err());
    }

    /// The main of a stored World Bank run (`run`: a copy of its events.jsonl, claims.jsonl, data/, shadow/ and
    /// computations/) as leaf_page asks for its page: the table of the run's first next_chart event, prepared as its
    /// candidates and picks calls left it (file, sheet, claims; no companion), with the relation its next_table_relation
    /// event kept when `kept` (none without that event), drawn as the run's next_chart templates, under the question of its
    /// next_catalogue event. Returns (question, prepared, drawn).
    fn stored_world_bank_main(run: &Path, kept: bool) -> (String, Prepared, Vec<String>) {
        let events: Vec<Value> = std::fs::read_to_string(run.join("events.jsonl"))
            .unwrap()
            .lines()
            .filter_map(|l| serde_json::from_str(l).ok())
            .collect();
        let question = events
            .iter()
            .find(|e| e["type"] == "next_catalogue")
            .unwrap()["question"]
            .as_str()
            .unwrap()
            .to_string();
        let charts: Vec<&Value> = events
            .iter()
            .filter(|e| e["type"] == "next_chart")
            .collect();
        let main = charts[0]["table"].as_str().unwrap().to_string();
        let drawn: Vec<String> = charts
            .iter()
            .flat_map(|e| [e["template"].as_str(), e["second"]["template"].as_str()])
            .flatten()
            .map(str::to_string)
            .collect();
        let dataset = main.strip_suffix("@2").unwrap();
        let (mut args, mut sheet, mut picked) = (Map::new(), String::new(), None);
        for e in events
            .iter()
            .filter(|e| e["toolName"] == "newsroom_data_prepare")
        {
            if e["type"] == "tool_execution_start" {
                args = e["args"].as_object().cloned().unwrap_or_default();
                continue;
            }
            let d = &e["result"]["details"];
            if e["type"] != "tool_execution_end" || d["dataset"] != dataset {
                continue;
            }
            match d["mode"].as_str() {
                Some("candidates") => sheet = d["sheet"].as_str().unwrap().to_string(),
                Some("picks") => {
                    picked = Some((
                        d["filePath"].as_str().unwrap().to_string(),
                        d["claims"].as_array().cloned().unwrap(),
                    ))
                }
                _ => {}
            }
        }
        let relation = events
            .iter()
            .filter(|_| kept)
            .rfind(|e| {
                e["type"] == crate::next_flow::TABLE_RELATION_EVENT && e["table"] == main.as_str()
            })
            .and_then(|e| e["kept"].as_str())
            .map(|k| {
                *crate::shape_registry::RELATIONS
                    .iter()
                    .find(|r| format!("{r:?}") == k)
                    .unwrap_or_else(|| panic!("no relation {k}"))
            });
        let (file, claims) = picked.unwrap();
        let prepared = Prepared {
            id: main,
            title: String::new(),
            file,
            args,
            sheet,
            claims,
            places_zh: Vec::new(),
            companions: Vec::new(),
            chain: Vec::new(),
            asked: json!([]),
            relation,
        };
        (question, prepared, drawn)
    }

    /// The main of a stored World Bank run (STORED_WB_RUN, as stored_world_bank_main reads it, no relation kept; the
    /// catalogue env as the product's; run with --ignored) through leaf_request. Prints each recipe's outcome: the recipe
    /// whose request was made, or the recipe and stage it stopped at, and why.
    #[test]
    #[ignore]
    fn a_stored_world_bank_run_s_leaf_request() {
        let run = std::path::PathBuf::from(std::env::var("STORED_WB_RUN").unwrap());
        let catalogue =
            crate::next_flow::GroupCatalogue::from_env(|k| std::env::var(k).ok()).unwrap();
        let (question, prepared, drawn) = stored_world_bank_main(&run, false);
        let drawn: Vec<&str> = drawn.iter().map(String::as_str).collect();
        let main = prepared.id.clone();
        println!(
            "main {main} file {} claims {} drawn {drawn:?} question {question}",
            prepared.file,
            prepared.claims.len()
        );
        let got = leaf_request(
            &run,
            &[prepared],
            &drawn,
            &catalogue,
            (&question, ("标题", "导语", "栏目")),
            (&Default::default(), None),
            (false, false),
        );
        match &got {
            Ok((recipe, fill, _)) => println!(
                "WBRUN {main} recipe {} request made, {} rows",
                recipe.name,
                fill["rows"].as_array().map_or(0, Vec::len)
            ),
            Err((recipe, stage, why)) => {
                println!("WBRUN {main} recipe {recipe} stopped at {stage}: {why}")
            }
        }
        let reached = match &got {
            Ok((recipe, _, _)) => recipe.name.as_str(),
            Err((recipe, stage, _)) if *stage != "shape" => *recipe,
            Err((_, _, why)) => panic!("no recipe takes the shape: {why}"),
        };
        assert_eq!(reached, "column");
    }

    /// Each stored World Bank run of STORED_WB_RUNS (run folders, ':' between them; the catalogue env as the product's; run
    /// with --ignored) through leaf_request under the relation its table step kept (stored_world_bank_main): prints the
    /// picked recipe and each recipe passed over before it with why, or where the pick stopped. A measurement, no assert.
    #[test]
    #[ignore]
    fn stored_world_bank_runs_recipes_passed_over() {
        let runs = std::env::var("STORED_WB_RUNS").unwrap();
        let catalogue =
            crate::next_flow::GroupCatalogue::from_env(|k| std::env::var(k).ok()).unwrap();
        for run in runs.split(':').map(std::path::PathBuf::from) {
            let (question, prepared, drawn) = stored_world_bank_main(&run, true);
            let drawn: Vec<&str> = drawn.iter().map(String::as_str).collect();
            println!(
                "RUN {} main {} kept {:?} drawn {drawn:?}",
                run.display(),
                prepared.id,
                prepared.relation
            );
            match leaf_request(
                &run,
                &[prepared],
                &drawn,
                &catalogue,
                (&question, ("标题", "导语", "栏目")),
                (&Default::default(), None),
                (false, false),
            ) {
                Ok((recipe, _, passed)) => {
                    println!("  PICKED {}", recipe.name);
                    for p in passed {
                        println!("  PASSED {p}");
                    }
                }
                Err((recipe, stage, why)) => println!("  STOPPED {recipe}-{stage}: {why}"),
            }
        }
    }

    // A second topic through the same nodes: a World Bank ranking of eight economies (q5, its share aged 65 and above).
    #[test]
    #[ignore]
    fn a_stored_world_bank_ranking_run_draws_its_page() {
        let _command = crate::group_guard::command_for_test("investigate");
        let run = std::path::PathBuf::from(std::env::var("NEXT_WB_RANKING_RUN").unwrap());
        let worded = read_json(&run, "runtime/next-page.json").unwrap()["worded"].clone();
        let (top, bottom) = ("claim-1eb19a3841ee7437", "claim-b7c715e09a0075da");
        let targets = [
            Target::PageTitle,
            Target::PageDek,
            Target::Measure(1),
            Target::Heading(1),
            Target::Body(1),
            Target::HeroLabel {
                claim_id: top.into(),
                value_from: "first.value".into(),
            },
        ];
        let fields: BTreeMap<Target, String> = targets
            .into_iter()
            .filter_map(|t| Some((t.clone(), worded[format!("{t:?}")].as_str()?.to_string())))
            .collect();
        let chart = |relation, view, ids: &[&str]| Chart {
            relation,
            view,
            claim_ids: ids.iter().map(|id| id.to_string()).collect(),
            category: "country_iso3".into(),
            value: "value".into(),
        };
        let title = "Population ages 65 and above (% of total population)";
        let measure = next_pack::Measure {
            title: title.into(),
            name: title.into(),
            unit_code: Some("PC_POP".into()),
            unit_label: Some("Percentage of total population".into()),
            kind: None,
            times: vec!["2025".into()],
            axis: Axis::Country,
        };
        let page = Page {
            claims: [(top, "rank_top"), (bottom, "rank_bottom")]
                .iter()
                .map(|(id, kind)| Claim {
                    id: id.to_string(),
                    kind: kind.to_string(),
                    template: String::new(),
                })
                .collect(),
            charts: vec![
                chart(Relation::Change, View::FirstToLast, &[]),
                chart(Relation::Ranking, View::Slice, &[top, bottom]),
            ],
            templates: Vec::new(),
            sentences: BTreeMap::new(),
            places: Vec::new(),
            times: Vec::new(),
            measures: vec![measure.clone(), measure],
            plans: Vec::new(),
            scopes: vec![None, None],
        };
        let spec = ranking_page_spec(
            &run,
            &page,
            1,
            &fields,
            "SP.POP.65UP.TO.ZS@2",
            &WorldBank,
            "#c8553d",
        )
        .unwrap();
        let page = stored_page(&spec);
        let Card::Bar(card) = &spec.cards[0];
        assert_eq!(card.rows.len(), 8);
        for row in &card.rows {
            assert_eq!(page.ledger.get(&row.value.src), Some(&row.value.text));
        }
        for id in [top, bottom] {
            assert!(page.ledger.keys().any(|k| k.starts_with(id)), "{id}");
        }
        assert!(page.html.contains("世界银行"));
    }

